fn normalized_session_relative_path(rel: Option<&str>) -> Result<String, DaemonError> {
    let Some(rel) = rel.map(str::trim).filter(|rel| !rel.is_empty()) else {
        return Ok(String::new());
    };
    if rel.contains('\0') {
        return Err(DaemonError::Session(
            "Session file path contains a NUL byte".to_string(),
        ));
    }
    let mut parts = Vec::new();
    for component in std::path::Path::new(rel).components() {
        match component {
            std::path::Component::Normal(part) => parts.push(part.to_string_lossy().to_string()),
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir
            | std::path::Component::RootDir
            | std::path::Component::Prefix(_) => {
                return Err(DaemonError::Session(
                    "Session file path must stay inside the project".to_string(),
                ));
            }
        }
    }
    Ok(parts.join("/"))
}

fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or(0)
}

fn model_probe_control_usage(
    counter: &dyn TokenCounter,
    estimated_input: usize,
    response: &axocoatl_llm::ChatResponse,
) -> crate::git::ControlUsage {
    let usage = if response.usage.total() == 0 {
        axocoatl_core::TokenUsageStats::new(
            estimated_input,
            axocoatl_llm::estimate_response_output_tokens(counter, response),
        )
    } else {
        response.usage.clone()
    };
    crate::git::ControlUsage::known(None, 1, &usage)
}

fn lane_model_probe_request(model: &str) -> axocoatl_llm::ChatRequest {
    let mut request = axocoatl_llm::ChatRequest::simple(
        "Read the file README.md. Call the tool — do not describe the call.",
    );
    request.tools = vec![axocoatl_llm::ToolDefinition {
        name: "read_file".to_string(),
        description: "Read a file from the project".to_string(),
        parameters: serde_json::json!({
            "type": "object",
            "properties": { "path": { "type": "string" } },
            "required": ["path"],
        }),
        concurrency: Default::default(),
    }];
    // The probe is a bounded control-plane capability test. Thinking can
    // consume its entire deliberately small completion budget before the model
    // emits the one structured tool call being measured, so suppress it for
    // this call only. Ordinary Session, Automation, and tool turns still omit
    // the option and retain the model's configured reasoning behavior.
    request.provider_options = Some(serde_json::json!({"reasoning_effort": "none"}));
    request.max_tokens = Some(64);
    request.temperature = Some(0.0);
    request.model_override = Some(model.to_string());
    request
}

fn approved_session_setup(session: &Session) -> Result<Vec<String>, DaemonError> {
    match (
        session.environment.setup_command.as_deref(),
        session.environment.setup_approved,
    ) {
        (Some(command), true) if !command.trim().is_empty() => Ok(vec![command.trim().to_string()]),
        (Some(command), false) if !command.trim().is_empty() => Err(DaemonError::Session(format!(
            "Session '{}' needs approval before running its proposed setup command: {}",
            session.name,
            command.trim()
        ))),
        _ => Ok(Vec::new()),
    }
}

fn operator_preapproved_devcontainer_command(
    session: &Session,
    allow_post_create_command: bool,
) -> Option<String> {
    if session.environment.setup_approved
        || session.environment.state != SessionEnvironmentState::AwaitingApproval
        || !allow_post_create_command
        || session.environment.setup_reviewed
        || session.post_create_commands.is_empty()
    {
        return None;
    }
    let configured = session.post_create_commands.join(" && ");
    (session.environment.setup_command.as_deref() == Some(configured.as_str()))
        .then_some(configured)
}

/// Normal product work may use only a durably Ready Session. Environment
/// creation and repair are explicit lifecycle operations; a file, Git,
/// Preview, Terminal, or turn request must never convert a non-ready record
/// into an executable one as a side effect.
fn require_session_environment_ready(session: &Session) -> Result<(), DaemonError> {
    match session.environment.state {
        SessionEnvironmentState::Ready => Ok(()),
        SessionEnvironmentState::AwaitingApproval => Err(DaemonError::Session(format!(
            "Session '{}' needs setup approval before it is Ready",
            session.name
        ))),
        SessionEnvironmentState::Preparing => Err(DaemonError::Session(format!(
            "Session '{}' environment is still preparing; wait for it to become Ready",
            session.name
        ))),
        SessionEnvironmentState::Unprepared => Err(DaemonError::Session(format!(
            "Session '{}' environment is not prepared; review or rebuild it before continuing",
            session.name
        ))),
        SessionEnvironmentState::Failed => Err(DaemonError::Session(
            session.environment.error.clone().unwrap_or_else(|| {
                "Session environment failed; change or rebuild the runtime".to_string()
            }),
        )),
    }
}

const MISSING_E2B_RUNTIME_ID_ERROR: &str = "Axocoatl cannot verify or delete the E2B runtime left by an earlier build because its durable remote identity is missing. Check E2B for an older sandbox, then use Change runtime to explicitly prepare a replacement.";

fn unconfirmed_ready_e2b_runtime(session: &Session) -> Option<&SessionRuntimeIdentity> {
    (session.environment.state == SessionEnvironmentState::Ready)
        .then_some(session.environment.runtime.as_ref())
        .flatten()
        .filter(|runtime| runtime.backend == "e2b" && !runtime.cleanup_confirmed)
}

fn e2b_ownership_token(session_id: &str, generation: u64) -> String {
    format!("{session_id}:{generation}:{}", uuid::Uuid::new_v4())
}

/// Return the exact persisted provider token only when its structured owner
/// prefix names this Session and this preparation generation. Repository code
/// that once saw a writable legacy data root can copy or forge Session JSON;
/// local binding plus provider-metadata verification prevents a copied runtime
/// id/token from authorizing lifecycle work against another Session.
fn validate_e2b_ownership_token<'a>(
    session_id: &str,
    generation: u64,
    token: Option<&'a str>,
) -> Result<&'a str, DaemonError> {
    let token = token.ok_or_else(|| {
        DaemonError::Session(format!(
            "Session '{session_id}' has no durable E2B provider-ownership token; Axocoatl will not connect, pause, or delete an unproven remote runtime"
        ))
    })?;
    let expected_prefix = format!("{session_id}:{generation}:");
    let random = token.strip_prefix(&expected_prefix).ok_or_else(|| {
        DaemonError::Session(format!(
            "persisted E2B ownership token is not bound to Session '{session_id}' generation {generation}"
        ))
    })?;
    if uuid::Uuid::parse_str(random).is_err() {
        return Err(DaemonError::Session(format!(
            "persisted E2B ownership token for Session '{session_id}' is malformed"
        )));
    }
    Ok(token)
}

fn runtime_ownership_token<'a>(
    session: &Session,
    runtime: &'a SessionRuntimeIdentity,
) -> Result<&'a str, DaemonError> {
    validate_e2b_ownership_token(
        &session.id,
        session.environment.generation,
        runtime.ownership_token.as_deref(),
    )
}

fn creation_ownership_token<'a>(
    session: &Session,
    creation: &'a SessionRuntimeCreationAttempt,
) -> Result<&'a str, DaemonError> {
    validate_e2b_ownership_token(
        &session.id,
        session.environment.generation,
        Some(&creation.token),
    )
}

fn should_reattach_ready_e2b_on_startup(session: &Session, reattach_active_ready: bool) -> bool {
    reattach_active_ready && session.status != axocoatl_session::SessionStatus::Closed
}

fn e2b_reattach_coordinates(runtime: &SessionRuntimeIdentity) -> Result<(&str, &str), DaemonError> {
    let remote_root = runtime
        .remote_root
        .as_deref()
        .map(str::trim)
        .filter(|root| !root.is_empty() && std::path::Path::new(root).is_absolute())
        .ok_or_else(|| {
            DaemonError::Session(format!(
                "persisted E2B runtime '{}' is missing its exact absolute remote workspace root; Axocoatl will not guess or clone a replacement",
                runtime.id
            ))
        })?;
    let domain = runtime
        .data_plane_domain
        .as_deref()
        .ok_or_else(|| {
            DaemonError::Session(format!(
                "persisted E2B runtime '{}' is missing its exact data-plane domain; Axocoatl will not guess or clone a replacement",
                runtime.id
            ))
        })?;
    let domain = axocoatl_isolation::e2b::validate_data_plane_domain(domain)
        .map_err(|error| DaemonError::Session(error.to_string()))?;
    Ok((remote_root, domain))
}

/// Backfill exact backend provenance for legacy Ready Sessions. Podman has a
/// deterministic id, so it can be migrated without guessing. An E2B effective
/// image proves the old backend but not its opaque sandbox id; fail that record
/// closed rather than starting a second billable VM or claiming cleanup.
fn reconcile_legacy_runtime_identities(
    sessions: &mut SessionStore,
) -> Result<(usize, usize), DaemonError> {
    let legacy: Vec<Session> = sessions
        .list()
        .into_iter()
        .filter(|session| {
            session.environment.state == SessionEnvironmentState::Ready
                && session.environment.runtime.is_none()
        })
        .collect();
    let mut podman = 0;
    let mut e2b = 0;
    for session in &legacy {
        let legacy_e2b = session
            .environment
            .effective_image
            .as_deref()
            .is_some_and(|image| image.starts_with("e2b:"));
        let (state, runtime, error) = if legacy_e2b {
            e2b += 1;
            (
                SessionEnvironmentState::Failed,
                None,
                Some(MISSING_E2B_RUNTIME_ID_ERROR.to_string()),
            )
        } else {
            podman += 1;
            (
                SessionEnvironmentState::Ready,
                Some(SessionRuntimeIdentity {
                    backend: "podman".to_string(),
                    id: session.id.clone(),
                    remote_root: None,
                    control_plane: None,
                    data_plane_domain: None,
                    authority_fingerprint: None,
                    ownership_token: None,
                    cleanup_confirmed: false,
                }),
                None,
            )
        };
        sessions
            .set_environment(
                &session.id,
                state,
                session.environment.effective_image.clone(),
                runtime,
                session.environment.setup_results.clone(),
                error,
            )
            .map_err(|error| DaemonError::Session(error.to_string()))?;
    }
    Ok((podman, e2b))
}

/// Whether a persisted Session can own the deterministic local Podman name.
/// A missing legacy identity defaults to local unless an E2B image/creation
/// marker proves the backend was remote.
fn is_locally_attributable_session(session: &Session, default_local: bool) -> bool {
    if let Some(runtime) = session.environment.runtime.as_ref() {
        return runtime.backend == "podman";
    }
    if let Some(creation) = session.environment.runtime_creation.as_ref() {
        return creation.backend == "podman";
    }
    session
        .environment
        .effective_image
        .as_deref()
        .map_or(default_local, |image| !image.starts_with("e2b:"))
}

fn is_locally_attributable_recovery_record(
    record: &SessionRuntimeRecoveryRecord,
    default_local: bool,
) -> bool {
    let Some(environment) = record.environment.as_ref() else {
        // A canonical unloaded filename is sufficient authority for exact
        // deterministic Podman-name cleanup. It is not sufficient for any
        // remote provider request.
        return true;
    };
    if let Some(runtime) = environment.runtime.as_ref() {
        return runtime.backend == "podman";
    }
    if let Some(creation) = environment.runtime_creation.as_ref() {
        return creation.backend == "podman";
    }
    environment
        .effective_image
        .as_deref()
        .map_or(default_local, |image| !image.starts_with("e2b:"))
}

fn hardened_git_environment(clear_repository_environment: bool) -> Vec<String> {
    let mut argv = vec!["env".to_string()];
    if clear_repository_environment {
        for name in [
            "GIT_DIR",
            "GIT_WORK_TREE",
            "GIT_COMMON_DIR",
            "GIT_OBJECT_DIRECTORY",
            "GIT_ALTERNATE_OBJECT_DIRECTORIES",
            "GIT_INDEX_FILE",
            "GIT_NAMESPACE",
            "GIT_QUARANTINE_PATH",
            "GIT_SHALLOW_FILE",
        ] {
            argv.push("-u".to_string());
            argv.push(name.to_string());
        }
    }
    argv.extend(
        [
            "GIT_CONFIG_NOSYSTEM=1",
            "GIT_CONFIG_SYSTEM=/dev/null",
            "GIT_CONFIG_GLOBAL=/dev/null",
            "GIT_ATTR_NOSYSTEM=1",
            "GIT_CONFIG_COUNT=0",
            "GIT_CONFIG_PARAMETERS=",
            "GIT_TERMINAL_PROMPT=0",
            "GIT_ASKPASS=/bin/false",
            "GIT_SSH_COMMAND=/bin/false",
            "GIT_EXTERNAL_DIFF=/bin/false",
            "GIT_PAGER=cat",
            "GIT_EDITOR=/bin/false",
            "GIT_SEQUENCE_EDITOR=/bin/false",
            "GIT_OPTIONAL_LOCKS=0",
            "GIT_NO_REPLACE_OBJECTS=1",
        ]
        .into_iter()
        .map(str::to_string),
    );
    argv
}

fn append_hardened_git_command(argv: &mut Vec<String>) {
    argv.extend(
        [
            "git",
            "--no-optional-locks",
            "-c",
            "safe.directory=*",
            "-c",
            "core.hooksPath=/dev/null",
            "-c",
            "core.fsmonitor=false",
            "-c",
            "core.sshCommand=/bin/false",
            "-c",
            "credential.helper=",
            "-c",
            "diff.external=",
            "-c",
            "protocol.allow=never",
            "-c",
            "protocol.file.allow=always",
            "-c",
            "protocol.ext.allow=never",
            "-c",
            "gc.auto=0",
            "-c",
            "maintenance.auto=false",
            "-c",
            "commit.gpgSign=false",
            "-c",
            "tag.gpgSign=false",
        ]
        .into_iter()
        .map(str::to_string),
    );
}

fn session_git_arguments(cwd: &str, args: &[&str]) -> Vec<String> {
    let mut argv = hardened_git_environment(true);
    append_hardened_git_command(&mut argv);
    argv.extend([
        "-c".to_string(),
        "user.email=agent@axocoatl.local".to_string(),
        "-c".to_string(),
        "user.name=Axocoatl".to_string(),
        "-C".to_string(),
        cwd.to_string(),
    ]);
    argv.extend(args.iter().map(|arg| (*arg).to_string()));
    argv
}

fn passive_primary_git_config_key_allowed(key: &str) -> bool {
    let key = key.to_ascii_lowercase();
    if matches!(
        key.as_str(),
        "core.repositoryformatversion"
            | "core.filemode"
            | "core.bare"
            | "core.logallrefupdates"
            | "core.symlinks"
            | "core.ignorecase"
            | "core.precomposeunicode"
            | "core.autocrlf"
            | "core.eol"
            | "core.safecrlf"
            | "core.protecthfs"
            | "core.protectntfs"
            | "core.trustctime"
            | "core.checkstat"
            | "core.sharedrepository"
            // These command-bearing keys are allowed only because every
            // daemon Git invocation supplies a final, safe override.
            | "core.hookspath"
            | "core.fsmonitor"
            | "core.sshcommand"
            | "credential.helper"
            | "extensions.objectformat"
            | "user.name"
            | "user.email"
            | "init.defaultbranch"
            | "push.default"
            | "push.autosetupremote"
            | "push.followtags"
            | "pull.rebase"
            | "pull.ff"
            | "fetch.prune"
            | "fetch.prunetags"
    ) {
        return true;
    }
    let subsection_leaf_allowed = |prefix: &str, allowed: &[&str]| {
        key.strip_prefix(prefix)
            .and_then(|rest| rest.rsplit_once('.'))
            .is_some_and(|(subsection, leaf)| !subsection.is_empty() && allowed.contains(&leaf))
    };
    subsection_leaf_allowed(
        "remote.",
        &[
            "url",
            "pushurl",
            "fetch",
            "tagopt",
            "mirror",
            "prune",
            "prunetags",
            "skipdefaultupdate",
        ],
    ) || subsection_leaf_allowed(
        "branch.",
        &["remote", "pushremote", "merge", "rebase", "description"],
    )
}

/// E2B's create API selects a pre-built template; it does not accept the OCI
/// image chosen for an individual Axocoatl Session. Silently substituting the
/// configured template would make the persisted environment plan untrue, so
/// reject that combination before any remote VM is created.
fn require_e2b_template_compatible(
    session: &Session,
    configured_template: &str,
) -> Result<(), DaemonError> {
    let Some(image) = session
        .image
        .as_deref()
        .map(str::trim)
        .filter(|image| !image.is_empty())
    else {
        return Ok(());
    };
    Err(DaemonError::Session(format!(
        "Session '{}' requests OCI image '{image}', but the E2B backend can only start its configured template '{configured_template}' and cannot honor a per-Session image. Clear the Session's Base image or switch the sandbox backend to Podman before retrying.",
        session.name
    )))
}

fn bounded_setup_output(mut value: String) -> String {
    if value.len() <= SESSION_SETUP_OUTPUT_CAP {
        return value;
    }
    let mut end = SESSION_SETUP_OUTPUT_CAP;
    while !value.is_char_boundary(end) {
        end -= 1;
    }
    value.truncate(end);
    value.push_str("\n… setup output truncated …");
    value
}

fn persisted_setup_results(
    results: Vec<axocoatl_isolation::session_sandbox::SandboxSetupResult>,
) -> Vec<SessionSetupResult> {
    let completed_at = unix_now();
    results
        .into_iter()
        .map(|result| SessionSetupResult {
            command: result.command,
            exit_code: result.exit_code,
            stdout: result.stdout,
            stderr: result.stderr,
            completed_at,
        })
        .collect()
}

fn failed_setup_message(results: &[SessionSetupResult]) -> Option<String> {
    let failed = results.iter().find(|result| result.exit_code != 0)?;
    let detail = if !failed.stderr.trim().is_empty() {
        failed.stderr.lines().next().unwrap_or_default()
    } else {
        failed.stdout.lines().next().unwrap_or_default()
    };
    Some(format!(
        "setup command failed with exit {}: {}{}",
        failed.exit_code,
        failed.command,
        if detail.is_empty() {
            String::new()
        } else {
            format!(" ({detail})")
        }
    ))
}

fn inline_context_block(context: &[SessionTurnContextReference]) -> Option<String> {
    let mut lines = vec!["## Context the user attached:".to_string()];
    let mut included = false;
    for reference in context {
        match reference.kind.as_str() {
            "code_selection" => {
                included = true;
                let path = reference
                    .metadata
                    .get("path")
                    .and_then(serde_json::Value::as_str)
                    .or(reference.origin.as_deref())
                    .unwrap_or(reference.display_name.as_str());
                let start = reference
                    .metadata
                    .get("start_line")
                    .and_then(serde_json::Value::as_u64)
                    .unwrap_or(1);
                let end = reference
                    .metadata
                    .get("end_line")
                    .and_then(serde_json::Value::as_u64)
                    .unwrap_or(start);
                let range = if start == end {
                    start.to_string()
                } else {
                    format!("{start}-{end}")
                };
                let language = reference
                    .metadata
                    .get("language")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default();
                let content = reference
                    .metadata
                    .get("content")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default();
                lines.push(format!("\n### File: `{path}` (lines {range})"));
                lines.push(format!("```{language}"));
                lines.push(content.to_string());
                lines.push("```".to_string());
            }
            "browser_selection" => {
                included = true;
                let url = reference
                    .metadata
                    .get("url")
                    .and_then(serde_json::Value::as_str)
                    .or(reference.origin.as_deref())
                    .unwrap_or("(unknown)");
                let selector = reference
                    .metadata
                    .get("selector")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default();
                let html = reference
                    .metadata
                    .get("html")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default();
                lines.push(format!("\n### DOM element on {url}"));
                if !selector.is_empty() {
                    lines.push(format!("Selector: `{selector}`"));
                }
                if !html.is_empty() {
                    lines.push("```html".to_string());
                    lines.push(html.to_string());
                    lines.push("```".to_string());
                }
            }
            _ => {}
        }
    }
    included.then(|| {
        lines.push(String::new());
        lines.join("\n")
    })
}

fn checkpoint_user_content(turn: &SessionTurn) -> String {
    inline_context_block(&turn.context).map_or_else(
        || turn.user_input.clone(),
        |context| format!("{context}\n\n{}", turn.user_input),
    )
}

/// Project canonical Session history into route-portable context for a Way.
///
/// A Way can deliberately select a different provider or model from the
/// Session actor. Provider-native assistant tool messages carry route-specific
/// ids, signatures, and replay blocks, so sending them to a lane would either
/// cross protocols or (once route-pinned) fail the lane before it starts.
/// Complete transactions are therefore omitted atomically. Ordinary User and
/// plain Assistant text remains in order; malformed/orphaned transactions fail
/// closed rather than being flattened into misleading prose.
fn project_way_provider_history(
    history: &[axocoatl_core::ChatMessage],
) -> Result<Vec<axocoatl_core::ChatMessage>, DaemonError> {
    use axocoatl_core::MessageRole;

    let invalid = |detail: &str| {
        DaemonError::Session(format!(
            "Explore several ways cannot safely project Session history: {detail}"
        ))
    };
    let mut projected = Vec::new();
    let mut index = 0_usize;
    while index < history.len() {
        let message = &history[index];
        match message.role {
            MessageRole::System => {
                if !message.tool_calls.is_empty() || message.tool_call_id.is_some() {
                    return Err(invalid("a System message contains tool fields"));
                }
                // Each lane receives its selected Agent's current system prompt.
                // Historical System authority is never imported into it.
                index += 1;
            }
            MessageRole::User => {
                if !message.tool_calls.is_empty() || message.tool_call_id.is_some() {
                    return Err(invalid("a User message contains tool fields"));
                }
                projected.push(message.clone());
                index += 1;
            }
            MessageRole::Assistant if message.tool_calls.is_empty() => {
                if message.tool_call_id.is_some() {
                    return Err(invalid("an Assistant message contains a tool-result id"));
                }
                projected.push(message.clone());
                index += 1;
            }
            MessageRole::Assistant => {
                if message.tool_call_id.is_some() {
                    return Err(invalid(
                        "an Assistant tool-call message also contains a tool-result id",
                    ));
                }
                let calls = &message.tool_calls;
                let mut matched = vec![false; calls.len()];
                for result_offset in 0..calls.len() {
                    let result_index = index.saturating_add(1).saturating_add(result_offset);
                    let Some(result) = history.get(result_index) else {
                        return Err(invalid("history ends inside a tool transaction"));
                    };
                    if result.role != MessageRole::Tool || !result.tool_calls.is_empty() {
                        return Err(invalid("a tool transaction is interrupted"));
                    }
                    let result_id = result.tool_call_id.as_deref().filter(|id| !id.is_empty());
                    let result_name = result.name.as_deref().filter(|name| !name.is_empty());
                    let match_index = calls.iter().enumerate().position(|(call_index, call)| {
                        if matched[call_index] {
                            return false;
                        }
                        let id_matches = result_id.is_none_or(|id| call.id == id);
                        let name_matches = result_name.is_none_or(|name| call.name == name);
                        (result_id.is_some() || result_name.is_some()) && id_matches && name_matches
                    });
                    let Some(match_index) = match_index else {
                        return Err(invalid("a tool result is unmatched or duplicated"));
                    };
                    matched[match_index] = true;
                }
                if matched.iter().any(|matched| !matched) {
                    return Err(invalid("a tool transaction is missing a result"));
                }
                index = index.saturating_add(1).saturating_add(calls.len());
            }
            MessageRole::Tool => return Err(invalid("history contains an orphan tool result")),
        }
    }
    Ok(projected)
}

fn checkpoint_token_count(counter: &dyn TokenCounter, text: &str) -> usize {
    const CHUNK_BYTES: usize = 32 * 1024;
    if text.len() <= CHUNK_BYTES {
        return counter.count_text(text);
    }
    let mut total = 0_usize;
    let mut start = 0_usize;
    while start < text.len() {
        let mut end = (start + CHUNK_BYTES).min(text.len());
        while end > start && !text.is_char_boundary(end) {
            end -= 1;
        }
        if end == start {
            end = text[start..]
                .char_indices()
                .nth(1)
                .map_or(text.len(), |(offset, _)| start + offset);
        }
        total = total.saturating_add(counter.count_text(&text[start..end]));
        start = end;
    }
    total
}

fn checkpoint_turn_minimum_bytes(turn: &SessionTurn) -> usize {
    let assistant_bytes = if turn.agent_outputs.is_empty() {
        turn.final_output
            .as_ref()
            .map_or(turn.partial_output.len(), String::len)
    } else {
        turn.agent_outputs
            .iter()
            .map(|output| output.output.len())
            .sum()
    };
    turn.user_input.len().saturating_add(assistant_bytes)
}

#[cfg(test)]
fn checkpoint_projection(
    counter: &dyn TokenCounter,
    turns: &[SessionTurn],
) -> Vec<axocoatl_memory::StoredMessage> {
    checkpoint_projection_with_policy(counter, turns, true)
}

fn checkpoint_projection_with_policy(
    counter: &dyn TokenCounter,
    turns: &[SessionTurn],
    replay_tool_transactions: bool,
) -> Vec<axocoatl_memory::StoredMessage> {
    let mut projected = Vec::new();
    for turn in turns {
        // Cancelled work remains fully durable in the canonical turn ledger
        // and visible Route, but it is not conversation context. Replaying its
        // user request and completed tool pairs invites a newly spawned model
        // to resume an explicitly stopped edit plan instead of following the
        // next prompt.
        if turn.status == SessionTurnLifecycle::Cancelled {
            continue;
        }
        let user_content = checkpoint_user_content(turn);
        projected.push(axocoatl_memory::StoredMessage {
            role: axocoatl_core::MessageRole::User,
            token_count: checkpoint_token_count(counter, &user_content),
            content: user_content,
            timestamp: turn.created_at / 1_000,
            name: None,
            tool_calls: Vec::new(),
            tool_call_id: None,
        });

        // Rebuild one provider assistant message per original response, followed
        // by every correlated result. Parallel calls must stay grouped: Anthropic
        // replay metadata on the first call describes the complete native block
        // array, and splitting that response makes the next request invalid.
        // Incomplete, legacy, malformed, or bounded/truncated groups remain
        // visible in Route evidence but are omitted atomically from provider
        // history instead of replaying an orphaned or protocol-invalid call.
        let mut projected_groups = HashSet::new();
        for started in turn
            .execution_events
            .iter()
            .filter(|_| replay_tool_transactions)
        {
            if started.event.kind != "tool_started" {
                continue;
            }
            let Some(agent_id) = started
                .event
                .metadata
                .get("agent_id")
                .and_then(serde_json::Value::as_str)
            else {
                continue;
            };
            let Some(response_group) = started
                .event
                .metadata
                .get("provider_response_group")
                .and_then(serde_json::Value::as_u64)
            else {
                continue;
            };
            if !projected_groups.insert((agent_id.to_string(), response_group)) {
                continue;
            }

            let mut group_starts = turn
                .execution_events
                .iter()
                .enumerate()
                .filter(|(_, event)| {
                    event.event.kind == "tool_started"
                        && event
                            .event
                            .metadata
                            .get("agent_id")
                            .and_then(serde_json::Value::as_str)
                            == Some(agent_id)
                        && event
                            .event
                            .metadata
                            .get("provider_response_group")
                            .and_then(serde_json::Value::as_u64)
                            == Some(response_group)
                })
                .collect::<Vec<_>>();
            if group_starts.is_empty() {
                continue;
            }
            let Some(provider_call_count) = group_starts
                .first()
                .and_then(|(_, event)| event.event.metadata.get("provider_call_count"))
                .and_then(serde_json::Value::as_u64)
                .and_then(|count| usize::try_from(count).ok())
                .filter(|count| *count > 0 && *count == group_starts.len())
            else {
                continue;
            };
            group_starts.sort_by_key(|(_, event)| {
                event
                    .event
                    .metadata
                    .get("provider_call_index")
                    .and_then(serde_json::Value::as_u64)
                    .unwrap_or(u64::MAX)
            });
            if group_starts
                .iter()
                .enumerate()
                .any(|(expected, (_, event))| {
                    event
                        .event
                        .metadata
                        .get("provider_call_index")
                        .and_then(serde_json::Value::as_u64)
                        != u64::try_from(expected).ok()
                        || event
                            .event
                            .metadata
                            .get("provider_call_count")
                            .and_then(serde_json::Value::as_u64)
                            != u64::try_from(provider_call_count).ok()
                })
            {
                continue;
            }

            let mut assistant_content: Option<String> = None;
            let mut tool_calls = Vec::with_capacity(group_starts.len());
            let mut tool_results = Vec::with_capacity(group_starts.len());
            let mut seen_call_occurrences = HashSet::with_capacity(group_starts.len());
            let mut consumed_result_indices = HashSet::with_capacity(group_starts.len());
            let mut replayable = true;
            for (start_index, group_start) in group_starts {
                let metadata = &group_start.event.metadata;
                let Some(provider_call_index) = metadata
                    .get("provider_call_index")
                    .and_then(serde_json::Value::as_u64)
                else {
                    replayable = false;
                    break;
                };
                if metadata
                    .get("call_id_truncated")
                    .and_then(serde_json::Value::as_bool)
                    != Some(false)
                {
                    replayable = false;
                    break;
                }
                if metadata
                    .get("tool_name_truncated")
                    .and_then(serde_json::Value::as_bool)
                    != Some(false)
                {
                    replayable = false;
                    break;
                }
                let Some(call_id) = metadata.get("call_id").and_then(serde_json::Value::as_str)
                else {
                    replayable = false;
                    break;
                };
                let Some(call_hash) = metadata
                    .get("call_id_sha256")
                    .and_then(serde_json::Value::as_str)
                else {
                    replayable = false;
                    break;
                };
                let Some(occurrence) = metadata
                    .get("occurrence")
                    .and_then(serde_json::Value::as_u64)
                else {
                    replayable = false;
                    break;
                };
                if !seen_call_occurrences.insert((call_hash.to_string(), occurrence)) {
                    replayable = false;
                    break;
                }
                let Some(tool_name) = metadata
                    .get("tool_name")
                    .and_then(serde_json::Value::as_str)
                    .filter(|value| !value.is_empty())
                else {
                    replayable = false;
                    break;
                };
                if metadata
                    .get("arguments_truncated")
                    .and_then(serde_json::Value::as_bool)
                    != Some(false)
                {
                    replayable = false;
                    break;
                }
                let Some(_executed_arguments) =
                    metadata.get("arguments").filter(|value| value.is_object())
                else {
                    replayable = false;
                    break;
                };
                if metadata
                    .get("provider_arguments_truncated")
                    .and_then(serde_json::Value::as_bool)
                    != Some(false)
                {
                    replayable = false;
                    break;
                }
                let Some(provider_arguments) = metadata
                    .get("provider_arguments")
                    .filter(|value| value.is_object())
                else {
                    replayable = false;
                    break;
                };
                if provider_call_index == 0 {
                    if metadata
                        .get("assistant_content_truncated")
                        .and_then(serde_json::Value::as_bool)
                        != Some(false)
                    {
                        replayable = false;
                        break;
                    }
                    let Some(group_content) = metadata
                        .get("assistant_content")
                        .and_then(serde_json::Value::as_str)
                    else {
                        replayable = false;
                        break;
                    };
                    assistant_content = Some(group_content.to_string());
                } else if metadata.contains_key("assistant_content")
                    || metadata.contains_key("assistant_content_truncated")
                {
                    replayable = false;
                    break;
                }

                if metadata
                    .get("provider_metadata_truncated")
                    .and_then(serde_json::Value::as_bool)
                    != Some(false)
                {
                    replayable = false;
                    break;
                }
                let Some(provider_metadata) = metadata
                    .get("provider_metadata")
                    .and_then(|value| {
                        serde_json::from_value::<axocoatl_core::ProviderMetadata>(value.clone())
                            .ok()
                    })
                    .filter(|metadata| !metadata.is_empty())
                else {
                    replayable = false;
                    break;
                };
                let Some((result_index, result)) = turn
                    .execution_events
                    .iter()
                    .enumerate()
                    .skip(start_index + 1)
                    .find(|(result_index, event)| {
                        !consumed_result_indices.contains(result_index)
                            && event.event.kind == "tool_result"
                            && event
                                .event
                                .metadata
                                .get("agent_id")
                                .and_then(serde_json::Value::as_str)
                                == Some(agent_id)
                            && event
                                .event
                                .metadata
                                .get("call_id_sha256")
                                .and_then(serde_json::Value::as_str)
                                == Some(call_hash)
                            && event
                                .event
                                .metadata
                                .get("occurrence")
                                .and_then(serde_json::Value::as_u64)
                                == Some(occurrence)
                    })
                else {
                    replayable = false;
                    break;
                };
                consumed_result_indices.insert(result_index);
                if result
                    .event
                    .metadata
                    .get("call_id_truncated")
                    .and_then(serde_json::Value::as_bool)
                    != Some(false)
                    || result
                        .event
                        .metadata
                        .get("tool_name_truncated")
                        .and_then(serde_json::Value::as_bool)
                        != Some(false)
                {
                    replayable = false;
                    break;
                }
                if result
                    .event
                    .metadata
                    .get("tool_name")
                    .and_then(serde_json::Value::as_str)
                    != Some(tool_name)
                {
                    replayable = false;
                    break;
                }
                if result
                    .event
                    .metadata
                    .get("result_truncated")
                    .and_then(serde_json::Value::as_bool)
                    != Some(false)
                {
                    replayable = false;
                    break;
                }
                let Some(result_value) = result.event.metadata.get("result") else {
                    replayable = false;
                    break;
                };
                let Ok(arguments_json) = serde_json::to_string(provider_arguments) else {
                    replayable = false;
                    break;
                };
                let Ok(result_content) = serde_json::to_string(result_value) else {
                    replayable = false;
                    break;
                };
                tool_calls.push(axocoatl_memory::StoredToolCall {
                    id: call_id.to_string(),
                    name: tool_name.to_string(),
                    arguments_json,
                    provider_metadata,
                });
                tool_results.push((
                    call_id.to_string(),
                    tool_name.to_string(),
                    result_content,
                    result.recorded_at,
                ));
            }
            if !replayable || tool_calls.len() != tool_results.len() {
                continue;
            }
            let Some(assistant_content) = assistant_content else {
                continue;
            };
            projected.push(axocoatl_memory::StoredMessage {
                role: axocoatl_core::MessageRole::Assistant,
                token_count: checkpoint_token_count(counter, &assistant_content),
                content: assistant_content,
                timestamp: started.recorded_at / 1_000,
                name: None,
                tool_calls,
                tool_call_id: None,
            });
            for (call_id, tool_name, result_content, recorded_at) in tool_results {
                projected.push(axocoatl_memory::StoredMessage {
                    role: axocoatl_core::MessageRole::Tool,
                    token_count: checkpoint_token_count(counter, &result_content),
                    content: result_content,
                    timestamp: recorded_at / 1_000,
                    name: Some(tool_name),
                    tool_calls: Vec::new(),
                    tool_call_id: Some(call_id),
                });
            }
        }

        if turn.agent_outputs.is_empty() {
            if let Some(content) = turn
                .final_output
                .as_ref()
                .or_else(|| (!turn.partial_output.is_empty()).then_some(&turn.partial_output))
            {
                projected.push(axocoatl_memory::StoredMessage {
                    role: axocoatl_core::MessageRole::Assistant,
                    token_count: checkpoint_token_count(counter, content),
                    content: content.clone(),
                    timestamp: turn.updated_at / 1_000,
                    name: None,
                    tool_calls: Vec::new(),
                    tool_call_id: None,
                });
            }
        } else {
            for output in &turn.agent_outputs {
                projected.push(axocoatl_memory::StoredMessage {
                    role: axocoatl_core::MessageRole::Assistant,
                    token_count: checkpoint_token_count(counter, &output.output),
                    content: output.output.clone(),
                    timestamp: output.recorded_at / 1_000,
                    name: None,
                    tool_calls: Vec::new(),
                    tool_call_id: None,
                });
            }
            let completed_len = turn
                .agent_outputs
                .iter()
                .map(|output| output.output.len())
                .sum::<usize>();
            if let Some(tail) = turn
                .partial_output
                .get(completed_len..)
                .filter(|tail| !tail.is_empty())
                .map(str::to_string)
            {
                projected.push(axocoatl_memory::StoredMessage {
                    role: axocoatl_core::MessageRole::Assistant,
                    token_count: checkpoint_token_count(counter, &tail),
                    content: tail,
                    timestamp: turn.updated_at / 1_000,
                    name: None,
                    tool_calls: Vec::new(),
                    tool_call_id: None,
                });
            }
        }
    }
    projected
}

struct BoundedCheckpointProjection {
    checkpoint: axocoatl_memory::AgentCheckpoint,
    history_truncated: bool,
    behavior_state_dropped: bool,
}

#[allow(clippy::too_many_arguments)]
fn bounded_checkpoint_projection(
    counter: &dyn TokenCounter,
    turns: &[SessionTurn],
    version: u64,
    agent_id: String,
    checkpoint_time: u64,
    cumulative_token_usage: axocoatl_core::TokenUsageStats,
    cumulative_token_usage_known: bool,
    behavior_state: Option<String>,
    replay_tool_transactions: bool,
) -> Result<BoundedCheckpointProjection, axocoatl_memory::MemoryError> {
    let mut checkpoint = axocoatl_memory::AgentCheckpoint {
        version,
        agent_id,
        checkpoint_time,
        session_messages: Vec::new(),
        cumulative_token_usage,
        cumulative_token_usage_known,
        behavior_state,
    };
    let mut behavior_state_dropped = false;
    let mut base_size = axocoatl_memory::encoded_checkpoint_size(&checkpoint)?;
    if base_size > axocoatl_memory::MAX_CHECKPOINT_BYTES && checkpoint.behavior_state.is_some() {
        checkpoint.behavior_state = None;
        behavior_state_dropped = true;
        base_size = axocoatl_memory::encoded_checkpoint_size(&checkpoint)?;
    }
    if base_size > axocoatl_memory::MAX_CHECKPOINT_BYTES {
        return Err(axocoatl_memory::MemoryError::Serialization(format!(
            "checkpoint metadata is {base_size} bytes; limit is {}",
            axocoatl_memory::MAX_CHECKPOINT_BYTES
        )));
    }

    let message_budget = axocoatl_memory::MAX_CHECKPOINT_BYTES
        .saturating_sub(base_size)
        .min(SESSION_CHECKPOINT_MESSAGE_CAP);
    let mut segments: VecDeque<Vec<axocoatl_memory::StoredMessage>> = VecDeque::new();
    let mut segment_bytes = 0_usize;
    let mut history_truncated = false;
    for turn in turns.iter().rev() {
        // Cancelled turns are canonical Route evidence, not provider-visible
        // restart context. Skip them before estimating the message budget so
        // an arbitrarily large stopped turn cannot evict older completed work
        // that would otherwise fit in the bounded recovery tail.
        if turn.status == SessionTurnLifecycle::Cancelled {
            continue;
        }
        if checkpoint_turn_minimum_bytes(turn) > message_budget.saturating_sub(segment_bytes) {
            history_truncated = true;
            break;
        }
        let segment = checkpoint_projection_with_policy(
            counter,
            std::slice::from_ref(turn),
            replay_tool_transactions,
        );
        if segment.is_empty() {
            continue;
        }
        let encoded = axocoatl_memory::encoded_checkpoint_messages_size(&segment)?;
        if encoded > message_budget.saturating_sub(segment_bytes) {
            history_truncated = true;
            break;
        }
        segment_bytes = segment_bytes.saturating_add(encoded);
        segments.push_front(segment);
    }

    checkpoint.session_messages = segments.iter().flatten().cloned().collect();
    let mut encoded_size = axocoatl_memory::encoded_checkpoint_size(&checkpoint)?;
    // Separate segment vector prefixes make `segment_bytes` conservative, but
    // retain an exact fail-safe if the persistence encoding ever changes.
    while encoded_size > axocoatl_memory::MAX_CHECKPOINT_BYTES && segments.pop_front().is_some() {
        history_truncated = true;
        checkpoint.session_messages = segments.iter().flatten().cloned().collect();
        encoded_size = axocoatl_memory::encoded_checkpoint_size(&checkpoint)?;
    }
    if encoded_size > axocoatl_memory::MAX_CHECKPOINT_BYTES {
        return Err(axocoatl_memory::MemoryError::Serialization(format!(
            "bounded checkpoint is {encoded_size} bytes; limit is {}",
            axocoatl_memory::MAX_CHECKPOINT_BYTES
        )));
    }

    Ok(BoundedCheckpointProjection {
        checkpoint,
        history_truncated,
        behavior_state_dropped,
    })
}

fn checkpoint_visible_matches(
    existing: &[axocoatl_memory::StoredMessage],
    projected: &[axocoatl_memory::StoredMessage],
) -> bool {
    existing.len() == projected.len()
        && existing.iter().zip(projected).all(|(left, right)| {
            left.role == right.role
                && left.content == right.content
                && left.name == right.name
                && left.tool_call_id == right.tool_call_id
                && left.tool_calls.len() == right.tool_calls.len()
                && left
                    .tool_calls
                    .iter()
                    .zip(&right.tool_calls)
                    .all(|(left_call, right_call)| {
                        left_call.id == right_call.id
                            && left_call.name == right_call.name
                            && left_call.arguments_json == right_call.arguments_json
                            && left_call.provider_metadata == right_call.provider_metadata
                    })
        })
}

fn truncate_utf8(value: &str, max_bytes: usize) -> String {
    if value.len() <= max_bytes {
        return value.to_string();
    }
    const SUFFIX: &str = "…(truncated)";
    if max_bytes <= SUFFIX.len() {
        let mut end = max_bytes;
        while end > 0 && !SUFFIX.is_char_boundary(end) {
            end -= 1;
        }
        return SUFFIX[..end].to_string();
    }
    let mut end = (max_bytes - SUFFIX.len()).min(value.len());
    while end > 0 && !value.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}{SUFFIX}", &value[..end])
}

fn bounded_tool_json(value: &serde_json::Value) -> (serde_json::Value, bool) {
    let encoded = serde_json::to_vec(value).unwrap_or_default();
    if encoded.len() <= SESSION_TOOL_EVENT_VALUE_CAP {
        return (value.clone(), false);
    }
    let rendered = serde_json::to_string(value).unwrap_or_default();
    (
        serde_json::json!({
            "truncated": true,
            "original_bytes": encoded.len(),
            "preview": truncate_utf8(&rendered, SESSION_TOOL_EVENT_PREVIEW_CAP),
        }),
        true,
    )
}

#[allow(clippy::too_many_arguments)]
fn session_tool_execution_event(
    turn_id: &str,
    agent_id: &str,
    call_id: &str,
    occurrence: u64,
    tool_name: &str,
    kind: &str,
    value_key: &str,
    value: &serde_json::Value,
    is_error: Option<bool>,
) -> (String, RecordTurnExecution) {
    session_tool_execution_event_inner(
        turn_id, agent_id, call_id, occurrence, tool_name, kind, value_key, value, None, is_error,
    )
}

/// Coordinator workers use Session-scoped runtime/checkpoint identities while
/// durable Route and UI evidence remains attributed to the configured logical
/// Agent. Standalone chunks carry no source and stay on their outer Agent.
fn logical_tool_source_agent<'a>(source_agent: Option<&'a str>, outer_agent: &'a str) -> &'a str {
    source_agent
        .map(|source| {
            source
                .rsplit_once(":worker:")
                .map_or(source, |(_, logical)| logical)
        })
        .unwrap_or(outer_agent)
}

fn agent_chunk_stream_frame(
    chunk: &axocoatl_actor::AgentStreamChunk,
    workflow: &str,
    outer_agent: &str,
    turn_id: Option<&str>,
    tool_occurrence: Option<u64>,
) -> crate::stream::StreamFrame {
    use crate::stream::StreamFrame;
    use axocoatl_actor::AgentStreamChunk;

    match chunk {
        AgentStreamChunk::Text(delta) => StreamFrame::Token {
            workflow: workflow.to_string(),
            agent: outer_agent.to_string(),
            turn_id: turn_id.map(String::from),
            delta: delta.clone(),
        },
        AgentStreamChunk::Reasoning(delta) => StreamFrame::Reasoning {
            workflow: workflow.to_string(),
            agent: outer_agent.to_string(),
            turn_id: turn_id.map(String::from),
            delta: delta.clone(),
        },
        AgentStreamChunk::ToolCallStarted {
            source_agent,
            id,
            name,
            arguments,
            ..
        } => StreamFrame::ToolCall {
            workflow: workflow.to_string(),
            agent: logical_tool_source_agent(source_agent.as_deref(), outer_agent).to_string(),
            turn_id: turn_id.map(String::from),
            call_id: id.clone(),
            occurrence: tool_occurrence.expect("tool start has an occurrence"),
            name: name.clone(),
            phase: "start".to_string(),
            arguments: Some(arguments.clone()),
            result: None,
            is_error: false,
        },
        AgentStreamChunk::ToolCallResult {
            source_agent,
            id,
            name,
            result,
            is_error,
        } => StreamFrame::ToolCall {
            workflow: workflow.to_string(),
            agent: logical_tool_source_agent(source_agent.as_deref(), outer_agent).to_string(),
            turn_id: turn_id.map(String::from),
            call_id: id.clone(),
            occurrence: tool_occurrence.expect("tool result has an occurrence"),
            name: name.clone(),
            phase: "result".to_string(),
            arguments: None,
            result: Some(result.clone()),
            is_error: *is_error,
        },
    }
}

fn coordinator_worker_runtime_id(worker_scope: Option<&str>, worker_id: &str) -> AgentId {
    AgentId::new(
        worker_scope
            .map(|scope| format!("{scope}:worker:{worker_id}"))
            .unwrap_or_else(|| worker_id.to_string()),
    )
}

#[allow(clippy::too_many_arguments)]
fn session_tool_execution_event_with_provider_metadata(
    turn_id: &str,
    agent_id: &str,
    call_id: &str,
    occurrence: u64,
    tool_name: &str,
    kind: &str,
    value_key: &str,
    value: &serde_json::Value,
    provider_arguments: &serde_json::Value,
    provider_response_group: u64,
    provider_call_index: usize,
    provider_call_count: usize,
    assistant_content: Option<&str>,
    provider_metadata: &axocoatl_core::ProviderMetadata,
    is_error: Option<bool>,
) -> (String, RecordTurnExecution) {
    let (operation, mut event) = session_tool_execution_event_inner(
        turn_id,
        agent_id,
        call_id,
        occurrence,
        tool_name,
        kind,
        value_key,
        value,
        Some(provider_metadata),
        is_error,
    );
    let (provider_arguments, provider_arguments_truncated) = bounded_tool_json(provider_arguments);
    event
        .metadata
        .insert("provider_arguments".to_string(), provider_arguments);
    event.metadata.insert(
        "provider_arguments_truncated".to_string(),
        serde_json::Value::Bool(provider_arguments_truncated),
    );
    event.metadata.insert(
        "provider_response_group".to_string(),
        serde_json::Value::Number(provider_response_group.into()),
    );
    event.metadata.insert(
        "provider_call_index".to_string(),
        serde_json::Value::Number(
            u64::try_from(provider_call_index)
                .unwrap_or(u64::MAX)
                .into(),
        ),
    );
    event.metadata.insert(
        "provider_call_count".to_string(),
        serde_json::Value::Number(
            u64::try_from(provider_call_count)
                .unwrap_or(u64::MAX)
                .into(),
        ),
    );
    if let Some(assistant_content) = assistant_content {
        let (assistant_content, assistant_content_truncated) =
            bounded_tool_json(&serde_json::Value::String(assistant_content.to_string()));
        event
            .metadata
            .insert("assistant_content".to_string(), assistant_content);
        event.metadata.insert(
            "assistant_content_truncated".to_string(),
            serde_json::Value::Bool(assistant_content_truncated),
        );
    }
    (operation, event)
}

#[allow(clippy::too_many_arguments)]
fn session_tool_execution_event_inner(
    turn_id: &str,
    agent_id: &str,
    call_id: &str,
    occurrence: u64,
    tool_name: &str,
    kind: &str,
    value_key: &str,
    value: &serde_json::Value,
    provider_metadata: Option<&axocoatl_core::ProviderMetadata>,
    is_error: Option<bool>,
) -> (String, RecordTurnExecution) {
    use sha2::{Digest, Sha256};

    let identity = format!("{agent_id}\0{occurrence}\0{call_id}");
    let identity_sha256 = format!("{:x}", Sha256::digest(identity.as_bytes()));
    let mut metadata = serde_json::Map::new();
    metadata.insert(
        "agent_id".to_string(),
        serde_json::Value::String(truncate_utf8(agent_id, 512)),
    );
    metadata.insert(
        "tool_name".to_string(),
        serde_json::Value::String(truncate_utf8(tool_name, 512)),
    );
    metadata.insert(
        "tool_name_truncated".to_string(),
        serde_json::Value::Bool(tool_name.len() > 512),
    );
    metadata.insert(
        "call_id".to_string(),
        serde_json::Value::String(truncate_utf8(call_id, 1024)),
    );
    metadata.insert(
        "call_id_truncated".to_string(),
        serde_json::Value::Bool(call_id.len() > 1024),
    );
    metadata.insert(
        "call_id_sha256".to_string(),
        serde_json::Value::String(format!("{:x}", Sha256::digest(call_id.as_bytes()))),
    );
    metadata.insert(
        "occurrence".to_string(),
        serde_json::Value::Number(occurrence.into()),
    );
    let (bounded_value, value_truncated) = bounded_tool_json(value);
    metadata.insert(value_key.to_string(), bounded_value);
    metadata.insert(
        format!("{value_key}_truncated"),
        serde_json::Value::Bool(value_truncated),
    );
    if let Some(provider_metadata) = provider_metadata {
        let encoded = serde_json::to_value(provider_metadata).unwrap_or_default();
        let (provider_metadata, provider_metadata_truncated) = bounded_tool_json(&encoded);
        metadata.insert("provider_metadata".to_string(), provider_metadata);
        metadata.insert(
            "provider_metadata_truncated".to_string(),
            serde_json::Value::Bool(provider_metadata_truncated),
        );
    }
    if let Some(is_error) = is_error {
        metadata.insert("is_error".to_string(), serde_json::Value::Bool(is_error));
    }
    (
        format!("tool:{turn_id}:{identity_sha256}:{kind}"),
        RecordTurnExecution {
            kind: kind.to_string(),
            execution_id: Some(truncate_utf8(call_id, 1024)),
            attempt_id: None,
            metadata,
        },
    )
}

fn reconcile_session_attachment_pins(
    accepted_turns: &[SessionTurn],
    attachments: &mut SessionAttachmentStore,
) -> Result<usize, DaemonError> {
    let mut pinned = 0_usize;
    for turn in accepted_turns {
        let turn_references: Vec<_> = turn
            .context
            .iter()
            .filter(|reference| {
                reference.kind == "upload" && reference.scope == TurnContextScope::ThisTurn
            })
            .cloned()
            .collect();
        if turn_references.is_empty() {
            continue;
        }
        for reference in &turn_references {
            if attachments.get(&reference.reference_id).is_some() {
                continue;
            }
            let blob_id = reference
                .metadata
                .get("blob_id")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string)
                .or_else(|| {
                    reference
                        .content_sha256
                        .as_ref()
                        .map(|sha| format!("sha256:{sha}"))
                })
                .ok_or_else(|| {
                    DaemonError::Session(format!(
                        "turn '{}' has upload context '{}' without an immutable blob id",
                        turn.id, reference.reference_id
                    ))
                })?;
            let size = reference
                .metadata
                .get("size")
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(0);
            let extraction = reference
                .metadata
                .get("extraction")
                .cloned()
                .map(serde_json::from_value)
                .transpose()
                .map_err(|error| DaemonError::Session(error.to_string()))?
                .unwrap_or_default();
            let mut metadata = reference.metadata.clone();
            metadata.remove("blob_id");
            metadata.remove("size");
            metadata.remove("extraction");
            attachments
                .create(CreateSessionAttachmentRef {
                    reference_id: Some(reference.reference_id.clone()),
                    session_id: turn.session_id.clone(),
                    blob_id,
                    display_name: reference.display_name.clone(),
                    declared_mime: reference.media_type.clone(),
                    size,
                    scope: TurnContextScope::ThisTurn,
                    extraction,
                    metadata,
                })
                .map_err(|error| DaemonError::Session(error.to_string()))?;
        }
        let reference_ids = turn_references
            .iter()
            .map(|reference| reference.reference_id.clone())
            .collect::<Vec<_>>();
        attachments
            .mark_consumed(&turn.session_id, &reference_ids, &turn.id)
            .map_err(|error| DaemonError::Session(error.to_string()))?;
        pinned += reference_ids.len();
    }
    Ok(pinned)
}

fn apply_session_attachment_detach(
    attachments: &mut SessionAttachmentStore,
    session_id: &str,
    reference_id: &str,
    used_by_turn: Option<&str>,
) -> Result<SessionAttachmentRef, axocoatl_session::SessionAttachmentError> {
    if let Some(turn_id) = used_by_turn {
        attachments.mark_consumed(session_id, &[reference_id.to_string()], turn_id)?;
        attachments.deactivate(session_id, reference_id)
    } else {
        attachments.detach(session_id, reference_id)
    }
}

fn session_attachment_used_by_turn<'a>(
    turns: &'a [SessionTurn],
    reference_id: &str,
) -> Option<&'a str> {
    turns.iter().find_map(|turn| {
        turn.context
            .iter()
            .any(|context| context.reference_id == reference_id)
            .then_some(turn.id.as_str())
    })
}

fn judge_ranking_contract(candidate_indices: &[usize]) -> String {
    let indices = candidate_indices
        .iter()
        .map(usize::to_string)
        .collect::<Vec<_>>()
        .join(", ");
    format!(
        "Candidate indexes are exactly [{indices}]. Return every index exactly once. \
         Assign unique integer ranks that are a permutation of 1 through {count}; \
         ties are forbidden. The winner must be the candidate whose rank is 1. \
         If candidates are otherwise indistinguishable, break the tie by lower \
         candidate index and say that the tie was broken deterministically.",
        count = candidate_indices.len(),
    )
}

#[derive(serde::Deserialize)]
struct PlanningScope {
    #[serde(default)]
    files: Vec<String>,
}

fn parse_planning_scope(content: &str) -> Result<Vec<String>, serde_json::Error> {
    serde_json::from_str::<PlanningScope>(crate::git::unfence_json(content))
        .map(|scope| scope.files)
}

fn validate_planning_plan(plan: &crate::git::Plan) -> Result<(), String> {
    if plan.summary.trim().is_empty() {
        return Err("summary is empty".to_string());
    }
    if plan.steps.is_empty() {
        return Err("no implementation steps were returned".to_string());
    }
    for (index, step) in plan.steps.iter().enumerate() {
        if step.path.trim().is_empty() {
            return Err(format!("implementation step {} has no path", index + 1));
        }
        if step.change.trim().is_empty() {
            return Err(format!("implementation step {} has no change", index + 1));
        }
        if crate::git::looks_like_test(step.path.trim()) {
            return Err(format!(
                "implementation step {} changes a test; existing checks must remain the independent arbiter",
                index + 1
            ));
        }
    }
    if plan.acceptance.is_empty() || plan.acceptance.iter().any(|item| item.trim().is_empty()) {
        return Err("acceptance evidence is empty".to_string());
    }
    if plan
        .constraints
        .iter()
        .any(|constraint| constraint.trim().is_empty())
    {
        return Err("a constraint is empty".to_string());
    }
    Ok(())
}

fn ways_control_input(prompt: String) -> axocoatl_core::AgentInput {
    axocoatl_core::AgentInput::text(prompt)
        .with_response_format_override(Some(axocoatl_core::ResponseFormat::Json))
        .with_reasoning_disabled(true)
        .with_stateless(true)
}

fn ways_control_role_error(role: &AgentRoleYaml, purpose: &str, agent_id: &str) -> Option<String> {
    match role {
        AgentRoleYaml::Autonomous => None,
        AgentRoleYaml::Coordinator => Some(format!(
            "{purpose} agent '{agent_id}' is a Coordinator; Plan and Judge require one autonomous Agent so the schema and measured control-call boundary remain exact"
        )),
        AgentRoleYaml::Worker => Some(format!(
            "{purpose} agent '{agent_id}' is coordinator-owned and cannot run directly"
        )),
    }
}

/// Runtime ownership for one unresolved attempt set.
///
/// The durable manifest says what exists; this entry owns the process-local
/// things that must be joined before those files may be removed. A completed
/// lane deliberately stays here until Keep or Discard so cleanup has one path
/// for successful, failed, and still-running sets.
struct ActiveAttemptRun {
    set_id: String,
    actors: Vec<(AgentId, ractor::ActorRef<axocoatl_actor::AgentMessage>)>,
    tasks: Vec<tokio::task::JoinHandle<()>>,
    /// One real filesystem boundary per lane. Stopping these also kills any
    /// background command or PTY an attempt created outside its actor task.
    sandboxes: Vec<Arc<dyn Sandbox>>,
}

/// Owns resources created while an attempt set is still being launched.
///
/// The HTTP request can disappear at any await. Until the complete runtime is
/// published in `active_attempts`, this guard makes cancellation terminate the
/// actors and exact-remove every lane container plus dependency volume. The
/// durable unresolved set remains visible so Discard can finish metadata and
/// clone cleanup after a retry/restart.
struct AttemptLaunchGuard {
    actors: Vec<(AgentId, ractor::ActorRef<axocoatl_actor::AgentMessage>)>,
    container_ids: Vec<String>,
    agent_registry: AgentRegistry,
    armed: bool,
}

impl AttemptLaunchGuard {
    fn new(agent_registry: AgentRegistry) -> Self {
        Self {
            actors: Vec::new(),
            container_ids: Vec::new(),
            agent_registry,
            armed: true,
        }
    }

    fn track_container(&mut self, container_id: String) {
        self.container_ids.push(container_id);
    }

    fn track_actor(
        &mut self,
        actor_id: AgentId,
        actor: ractor::ActorRef<axocoatl_actor::AgentMessage>,
    ) {
        self.actors.push((actor_id, actor));
    }

    fn disarm(&mut self) {
        self.armed = false;
    }
}

impl Drop for AttemptLaunchGuard {
    fn drop(&mut self) {
        if !self.armed {
            return;
        }
        for (_, actor) in &self.actors {
            actor.kill();
        }
        let Ok(runtime) = tokio::runtime::Handle::try_current() else {
            return;
        };
        let actors = std::mem::take(&mut self.actors);
        let containers = std::mem::take(&mut self.container_ids);
        let registry = self.agent_registry.clone();
        runtime.spawn(async move {
            for (actor_id, actor) in actors {
                let _ = actor.kill_and_wait(Some(Duration::from_secs(5))).await;
                registry.remove(&actor_id).await;
            }
            if let Err(error) = SessionSandbox::remove_named_many_with_dependencies(
                &containers,
                ATTEMPT_CONTAINER_STOP_TIMEOUT,
            )
            .await
            {
                tracing::error!(%error, "cancelled attempt launch cleanup was incomplete");
            }
        });
    }
}

