    #[cfg(unix)]
    #[tokio::test]
    async fn recovery_git_rejects_filters_and_cannot_run_primary_hooks() {
        use std::os::unix::fs::PermissionsExt;
        use std::process::Command;

        let workspace = tempfile::tempdir().unwrap();
        let outside = tempfile::tempdir().unwrap();
        let sentinel = outside.path().join("executed");
        let helper = outside.path().join("helper.sh");
        std::fs::write(
            &helper,
            format!("#!/bin/sh\ntouch '{}'\ncat\n", sentinel.display()),
        )
        .unwrap();
        std::fs::set_permissions(&helper, std::fs::Permissions::from_mode(0o700)).unwrap();
        let git = |args: &[&str]| {
            let output = Command::new("git")
                .arg("-C")
                .arg(workspace.path())
                .args(args)
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "git {args:?}: {}",
                String::from_utf8_lossy(&output.stderr)
            );
            String::from_utf8_lossy(&output.stdout).trim().to_string()
        };
        git(&["init", "-q"]);
        git(&["config", "user.email", "test@example.invalid"]);
        git(&["config", "user.name", "Test"]);
        std::fs::write(workspace.path().join("tracked.txt"), "original\n").unwrap();
        git(&["add", "tracked.txt"]);
        git(&["commit", "-q", "-m", "initial"]);
        std::fs::write(
            workspace.path().join(".gitattributes"),
            "*.txt filter=pwn\n",
        )
        .unwrap();
        git(&["config", "filter.pwn.clean", helper.to_str().unwrap()]);

        let sandbox: Arc<dyn Sandbox> = Arc::new(LocalGitSandbox::new(workspace.path()));
        let workspace_root = SecureDir::open(workspace.path()).unwrap();
        let error =
            AxocoatlDaemon::validate_passive_primary_git_boundary(&sandbox, &workspace_root)
                .await
                .unwrap_err()
                .to_string();
        assert!(error.contains("filter.pwn.clean"), "{error}");
        assert!(
            !sentinel.exists(),
            "config admission executed a clean filter"
        );

        git(&["config", "--unset-all", "filter.pwn.clean"]);
        let hook = workspace.path().join(".git/hooks/reference-transaction");
        std::fs::copy(&helper, &hook).unwrap();
        std::fs::set_permissions(&hook, std::fs::Permissions::from_mode(0o700)).unwrap();
        AxocoatlDaemon::validate_passive_primary_git_boundary(&sandbox, &workspace_root)
            .await
            .unwrap();
        let head = git(&["rev-parse", "HEAD"]);
        let result = AxocoatlDaemon::session_git_in_sandbox(
            &sandbox,
            &workspace.path().to_string_lossy(),
            &["update-ref", "refs/axo/passive-test", &head],
        )
        .await
        .unwrap();
        assert!(result.ok(), "{}", result.stderr);
        assert!(
            !sentinel.exists(),
            "primary reference hook executed during recovery"
        );
    }

    #[tokio::test]
    async fn session_agent_behavior_runs_global_hooks_before_any_tool_side_effect() {
        let executions = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let mut executor = ToolExecutor::new();
        executor.register_builtin(
            "external_side_effect",
            Arc::new(SessionHookSideEffect {
                executions: executions.clone(),
            }),
        );

        let mut hooks = axocoatl_tools::HookRegistry::new();
        hooks.register_global(Arc::new(axocoatl_tools::DenyListHook::new(vec![
            "external_side_effect".to_string(),
        ])));

        let checkpoints = tempfile::tempdir().unwrap();
        let counter: Arc<dyn TokenCounter> = Arc::new(ApproximateCounter::new().unwrap());
        let mut behavior = session_agent_base_behavior(
            Arc::new(SessionHookProbeLlm {
                calls: std::sync::atomic::AtomicUsize::new(0),
            }),
            counter,
            Arc::new(CheckpointStore::new(
                checkpoints.path(),
                CheckpointPolicy::None,
            )),
            Arc::new(executor),
            Arc::new(hooks),
            axocoatl_core::SamplingConfig::default(),
        );
        behavior
            .on_start(&axocoatl_core::AgentConfig::default())
            .await
            .unwrap();

        let output = behavior
            .execute(axocoatl_core::AgentInput::text(
                "Try the external side effect",
            ))
            .await
            .unwrap();

        assert_eq!(
            executions.load(std::sync::atomic::Ordering::SeqCst),
            0,
            "the Session behavior must run hooks before dispatching a tool"
        );
        assert_eq!(
            output.content,
            "The external tool was denied and did not run."
        );
        assert_eq!(output.tool_calls.len(), 1);
        assert!(output.tool_calls[0]
            .result
            .as_ref()
            .and_then(|result| result.get("error"))
            .and_then(serde_json::Value::as_str)
            .is_some_and(|error| error.contains("denied by policy")));
    }

