    #[test]
    fn operator_default_applies_only_to_exact_unreviewed_devcontainer_setup() {
        let (_data, _work, _store, mut session) =
            environment_test_session(Some("npm ci".into()), false);
        session.post_create_commands = vec!["npm ci".into()];
        session.environment.setup_reviewed = false;

        assert_eq!(
            operator_preapproved_devcontainer_command(&session, true).as_deref(),
            Some("npm ci")
        );
        assert!(operator_preapproved_devcontainer_command(&session, false).is_none());

        session.environment.setup_reviewed = true;
        assert!(operator_preapproved_devcontainer_command(&session, true).is_none());

        session.environment.setup_reviewed = false;
        session.environment.setup_command = Some("npm run changed".into());
        assert!(operator_preapproved_devcontainer_command(&session, true).is_none());

        session.environment.setup_command = Some("npm ci".into());
        session.post_create_commands.clear();
        assert!(operator_preapproved_devcontainer_command(&session, true).is_none());
    }

    #[test]
    fn ordinary_access_accepts_only_durable_ready_without_mutating_other_states() {
        let (_data, _work, _store, mut session) = environment_test_session(None, false);
        let cases = [
            (
                SessionEnvironmentState::Unprepared,
                "environment is not prepared",
            ),
            (
                SessionEnvironmentState::AwaitingApproval,
                "needs setup approval",
            ),
            (
                SessionEnvironmentState::Preparing,
                "environment is still preparing",
            ),
            (SessionEnvironmentState::Failed, "setup failed exactly"),
        ];
        for (state, expected) in cases {
            session.environment.state = state;
            session.environment.error =
                (state == SessionEnvironmentState::Failed).then(|| expected.to_string());
            let generation = session.environment.generation;
            let error = require_session_environment_ready(&session)
                .unwrap_err()
                .to_string();
            assert!(
                error.contains(expected),
                "unexpected {state:?} error: {error}"
            );
            assert_eq!(session.environment.state, state);
            assert_eq!(session.environment.generation, generation);
        }

        session.environment.state = SessionEnvironmentState::Ready;
        session.environment.error = None;
        assert!(require_session_environment_ready(&session).is_ok());
    }

    #[test]
    fn persisted_e2b_restart_matrix_requires_ready_unconfirmed_exact_coordinates() {
        let (_data, _work, _store, mut session) = environment_test_session(None, false);
        let runtime = SessionRuntimeIdentity {
            backend: "e2b".into(),
            id: "sandbox-exact".into(),
            remote_root: Some("/home/user/repository".into()),
            control_plane: Some("https://api.e2b.dev".into()),
            data_plane_domain: Some("e2b.app".into()),
            authority_fingerprint: Some("fingerprint".into()),
            ownership_token: Some(test_e2b_ownership_token(&session)),
            cleanup_confirmed: false,
        };
        session.environment.state = SessionEnvironmentState::Ready;
        session.environment.runtime = Some(runtime.clone());

        // Active Ready reconnects immediately; Closed Ready is the same exact
        // durable runtime but startup leaves it paused until explicit Reopen.
        assert_eq!(
            unconfirmed_ready_e2b_runtime(&session).map(|runtime| runtime.id.as_str()),
            Some("sandbox-exact")
        );
        assert!(should_reattach_ready_e2b_on_startup(&session, true));
        assert!(!should_reattach_ready_e2b_on_startup(&session, false));
        session.status = axocoatl_session::SessionStatus::Closed;
        assert!(unconfirmed_ready_e2b_runtime(&session).is_some());
        assert!(!should_reattach_ready_e2b_on_startup(&session, true));

        let (root, domain) = e2b_reattach_coordinates(&runtime).unwrap();
        assert_eq!(root, "/home/user/repository");
        assert_eq!(domain, "e2b.app");

        let mut interrupted = runtime.clone();
        session.environment.state = SessionEnvironmentState::Failed;
        assert!(unconfirmed_ready_e2b_runtime(&session).is_none());
        session.environment.state = SessionEnvironmentState::Ready;
        interrupted.cleanup_confirmed = true;
        session.environment.runtime = Some(interrupted);
        assert!(unconfirmed_ready_e2b_runtime(&session).is_none());

        let mut missing_root = runtime.clone();
        missing_root.remote_root = None;
        assert!(e2b_reattach_coordinates(&missing_root).is_err());
        let mut missing_domain = runtime;
        missing_domain.data_plane_domain = None;
        assert!(e2b_reattach_coordinates(&missing_domain).is_err());
        for malicious in [
            "user@e2b.app",
            "e2b.app:443",
            "e2b.app?token=x",
            "e2b.app#fragment",
            "e2b.app\n",
        ] {
            missing_domain.data_plane_domain = Some(malicious.into());
            assert!(e2b_reattach_coordinates(&missing_domain).is_err());
        }
    }

