    #[tokio::test]
    async fn cancelled_preparation_guard_marks_exact_generation_failed() {
        let (_data, _work, mut store, session) = environment_test_session(None, false);
        let preparing = store
            .set_environment(
                &session.id,
                SessionEnvironmentState::Preparing,
                None,
                None,
                Vec::new(),
                None,
            )
            .unwrap();
        let store = Arc::new(tokio::sync::Mutex::new(store));
        let guard_store = store.clone();
        let session_id = session.id.clone();
        let generation = preparing.environment.generation;
        let preparation = tokio::spawn(async move {
            let _guard = SessionPreparationStateGuard {
                session_id,
                local: false,
                session_store: guard_store,
                start_lock: Arc::new(tokio::sync::Mutex::new(())),
                generation,
                e2b_config: None,
                armed: true,
            };
            std::future::pending::<()>().await;
        });
        tokio::task::yield_now().await;
        preparation.abort();
        let _ = preparation.await;
        for _ in 0..50 {
            if store
                .lock()
                .await
                .get(&session.id)
                .is_some_and(|session| session.environment.state == SessionEnvironmentState::Failed)
            {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        let environment = store.lock().await.get(&session.id).unwrap().environment;
        assert_eq!(environment.state, SessionEnvironmentState::Failed);
        assert!(environment
            .error
            .as_deref()
            .is_some_and(|error| error.contains("cancelled")));
    }

    #[tokio::test]
    async fn shutdown_cancellation_retains_persisted_e2b_id_when_delete_fails() {
        let (api_url, mut requests, server) = start_fake_e2b_control_plane(vec![
            test_e2b_owned_list("persisted-before-shutdown", TEST_E2B_REQUEST_TOKEN),
            test_e2b_owned_sandbox("persisted-before-shutdown", TEST_E2B_REQUEST_TOKEN),
            test_http_response("503 Service Unavailable", "delete refused"),
        ])
        .await;
        let (_data, _work, mut store, session) = environment_test_session(None, false);
        let runtime_identity = SessionRuntimeIdentity {
            backend: "e2b".into(),
            id: "persisted-before-shutdown".into(),
            remote_root: Some("/home/user/repository".into()),
            control_plane: Some(api_url.clone()),
            data_plane_domain: Some("sandbox.test".into()),
            authority_fingerprint: Some(AxocoatlDaemon::e2b_authority_fingerprint("test-key")),
            ownership_token: Some(test_e2b_ownership_token(&session)),
            cleanup_confirmed: false,
        };
        let preparing = store
            .set_environment(
                &session.id,
                SessionEnvironmentState::Preparing,
                Some("e2b:base".into()),
                Some(runtime_identity),
                Vec::new(),
                None,
            )
            .unwrap();
        let store = Arc::new(tokio::sync::Mutex::new(store));
        let preparation = tokio::spawn({
            let store = store.clone();
            let session_id = session.id.clone();
            async move {
                let _guard = SessionPreparationStateGuard {
                    session_id,
                    local: false,
                    session_store: store,
                    start_lock: Arc::new(tokio::sync::Mutex::new(())),
                    generation: preparing.environment.generation,
                    e2b_config: Some(axocoatl_isolation::e2b::E2bConfig {
                        api_url,
                        api_key: "test-key".into(),
                        template: "base".into(),
                        domain: "sandbox.test".into(),
                    }),
                    armed: true,
                };
                std::future::pending::<()>().await;
            }
        });
        tokio::task::yield_now().await;
        preparation.abort();
        let _ = preparation.await;
        let list = requests
            .recv()
            .await
            .expect("checked shutdown ownership LIST");
        assert!(list.starts_with("GET /v2/sandboxes?"));
        let proof = requests
            .recv()
            .await
            .expect("checked shutdown ownership GET");
        assert!(proof.starts_with("GET /sandboxes/persisted-before-shutdown HTTP/1.1"));
        let delete = requests.recv().await.expect("checked shutdown DELETE");
        assert!(delete.starts_with("DELETE /sandboxes/persisted-before-shutdown HTTP/1.1"));
        server.await.unwrap();
        for _ in 0..50 {
            if store
                .lock()
                .await
                .get(&session.id)
                .is_some_and(|session| session.environment.state == SessionEnvironmentState::Failed)
            {
                break;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }
        let environment = store.lock().await.get(&session.id).unwrap().environment;
        let retained = environment
            .runtime
            .as_ref()
            .expect("persisted exact E2B id retained");
        assert_eq!(retained.id, "persisted-before-shutdown");
        assert!(!retained.cleanup_confirmed);
        assert!(environment
            .error
            .as_deref()
            .is_some_and(|error| error.contains("delete refused")));
    }

    fn projection_turn() -> SessionTurn {
        SessionTurn {
            id: "turn-a".to_string(),
            session_id: "ses-a".to_string(),
            user_input: "Explain this selection".to_string(),
            agent_id: Some("coder".to_string()),
            model: None,
            context: vec![SessionTurnContextReference {
                reference_id: "context:turn-a:0".to_string(),
                display_name: "src/lib.rs:4-5".to_string(),
                kind: "code_selection".to_string(),
                scope: TurnContextScope::ThisTurn,
                media_type: None,
                content_sha256: None,
                origin: Some("src/lib.rs".to_string()),
                metadata: serde_json::Map::from_iter([
                    ("path".to_string(), serde_json::json!("src/lib.rs")),
                    ("language".to_string(), serde_json::json!("rust")),
                    ("start_line".to_string(), serde_json::json!(4)),
                    ("end_line".to_string(), serde_json::json!(5)),
                    (
                        "content".to_string(),
                        serde_json::json!("fn answer() -> u8 { 42 }"),
                    ),
                ]),
            }],
            status: SessionTurnLifecycle::Completed,
            partial_output: "The function returns 42.".to_string(),
            final_output: Some("The function returns 42.".to_string()),
            error: None,
            created_at: 1_000,
            updated_at: 2_000,
            completed_at: Some(2_000),
            idempotency_key: Some("turn-a".to_string()),
            metadata: serde_json::Map::new(),
            execution_events: Vec::new(),
            agent_outputs: Vec::new(),
            superseded: false,
        }
    }

    #[test]
    fn checkpoint_projection_restores_hidden_inline_context() {
        let counter = ApproximateCounter::new().unwrap();
        let projected = checkpoint_projection(&counter, &[projection_turn()]);
        assert_eq!(projected.len(), 2);
        assert!(projected[0]
            .content
            .contains("## Context the user attached:"));
        assert!(projected[0].content.contains("`src/lib.rs` (lines 4-5)"));
        assert!(projected[0].content.contains("fn answer() -> u8 { 42 }"));
        assert!(projected[0].content.ends_with("Explain this selection"));
        assert_eq!(projected[1].content, "The function returns 42.");
    }

    #[test]
    fn oversized_cancelled_turn_cannot_evict_older_completed_checkpoint_context() {
        let counter = ApproximateCounter::new().unwrap();
        let completed = projection_turn();
        let mut cancelled = projection_turn();
        cancelled.id = "turn-cancelled-oversized".to_string();
        cancelled.status = SessionTurnLifecycle::Cancelled;
        cancelled.user_input =
            format!("stopped:{}", "x".repeat(SESSION_CHECKPOINT_MESSAGE_CAP + 1));
        cancelled.partial_output.clear();
        cancelled.final_output = Some(String::new());
        cancelled.agent_outputs.clear();
        cancelled.execution_events.clear();

        let bounded = bounded_checkpoint_projection(
            &counter,
            &[completed, cancelled],
            1,
            "cancelled-tail:coder".to_string(),
            3_000,
            Default::default(),
            true,
            None,
            true,
        )
        .unwrap();

        assert!(!bounded.history_truncated);
        assert_eq!(bounded.checkpoint.session_messages.len(), 2);
        assert!(bounded.checkpoint.session_messages[0]
            .content
            .ends_with("Explain this selection"));
        assert_eq!(
            bounded.checkpoint.session_messages[1].content,
            "The function returns 42."
        );
        assert!(bounded
            .checkpoint
            .session_messages
            .iter()
            .all(|message| !message.content.contains("stopped")));
    }

    #[tokio::test]
    async fn oversized_canonical_history_saves_a_recent_bounded_checkpoint_tail() {
        struct FastCounter;
        impl TokenCounter for FastCounter {
            fn count_text(&self, text: &str) -> usize {
                text.len().div_ceil(4)
            }

            fn count_messages(&self, messages: &[axocoatl_core::ChatMessage]) -> usize {
                messages
                    .iter()
                    .map(|message| {
                        message
                            .text_content()
                            .map_or(0, |text| self.count_text(text))
                    })
                    .sum()
            }

            fn count_tool_definition(&self, tool_json: &serde_json::Value) -> usize {
                self.count_text(&tool_json.to_string())
            }
        }
        let counter = FastCounter;
        let mut turns = Vec::new();
        for index in 0..66_u64 {
            let mut turn = projection_turn();
            turn.id = format!("turn-{index}");
            turn.user_input = format!("request-{index}");
            turn.partial_output.clear();
            turn.final_output = Some(format!("turn-{index}:{}", "x".repeat(1024 * 1024)));
            turn.created_at = 1_000 + index;
            turn.updated_at = 2_000 + index;
            turn.completed_at = Some(2_000 + index);
            turns.push(turn);
        }
        assert!(
            turns
                .iter()
                .map(checkpoint_turn_minimum_bytes)
                .sum::<usize>()
                > axocoatl_memory::MAX_CHECKPOINT_BYTES
        );

        let bounded = bounded_checkpoint_projection(
            &counter,
            &turns,
            1,
            "oversized-session:coder".to_string(),
            3_000,
            Default::default(),
            true,
            None,
            true,
        )
        .unwrap();
        assert!(bounded.history_truncated);
        assert!(!bounded.behavior_state_dropped);
        assert!(
            axocoatl_memory::encoded_checkpoint_size(&bounded.checkpoint).unwrap()
                <= axocoatl_memory::MAX_CHECKPOINT_BYTES
        );
        assert_ne!(
            bounded
                .checkpoint
                .session_messages
                .first()
                .map(|message| &message.role),
            Some(&axocoatl_core::MessageRole::Tool),
            "a bounded tail cannot begin with an orphan tool result"
        );
        assert!(bounded
            .checkpoint
            .session_messages
            .last()
            .is_some_and(|message| message.content.starts_with("turn-65:")));

        let data = tempfile::tempdir().unwrap();
        let store = axocoatl_memory::CheckpointStore::new(
            data.path(),
            axocoatl_memory::CheckpointPolicy::Manual,
        );
        store.save(&bounded.checkpoint).await.unwrap();

        let mut next = projection_turn();
        next.id = "turn-66".to_string();
        next.user_input = "continue after restart".to_string();
        next.partial_output.clear();
        next.final_output = Some("latest-after-boundary".to_string());
        turns.push(next);
        let next = bounded_checkpoint_projection(
            &counter,
            &turns,
            2,
            "oversized-session:coder".to_string(),
            4_000,
            Default::default(),
            true,
            None,
            true,
        )
        .unwrap();
        store.save(&next.checkpoint).await.unwrap();
        let restored = store
            .load_latest(&AgentId::new("oversized-session:coder"))
            .await
            .unwrap()
            .unwrap();
        assert_eq!(restored.version, 2);
        assert_eq!(
            restored
                .session_messages
                .last()
                .map(|message| message.content.as_str()),
            Some("latest-after-boundary")
        );
    }

    #[test]
    fn tool_event_schema_is_bounded_and_projection_restores_correlated_pair() {
        let provider_metadata = axocoatl_core::ProviderMetadata::from([
            ("axocoatl.route.slot".to_string(), "primary".to_string()),
            (
                "gemini.thought_signature".to_string(),
                "exact-signature".to_string(),
            ),
        ]);
        let (start_operation, started) = session_tool_execution_event_with_provider_metadata(
            "turn-a",
            "coder",
            "call-a",
            0,
            "read_file",
            "tool_started",
            "arguments",
            &serde_json::json!({"path":"sandbox/src/lib.rs"}),
            &serde_json::json!({"path":"src/lib.rs"}),
            1,
            0,
            1,
            Some("I will inspect the file."),
            &provider_metadata,
            None,
        );
        assert_eq!(
            started.metadata["arguments"],
            serde_json::json!({"path":"sandbox/src/lib.rs"})
        );
        assert_eq!(
            started.metadata["provider_arguments"],
            serde_json::json!({"path":"src/lib.rs"})
        );
        let (result_operation, result) = session_tool_execution_event(
            "turn-a",
            "coder",
            "call-a",
            0,
            "read_file",
            "tool_result",
            "result",
            &serde_json::json!({"content":"source"}),
            Some(false),
        );
        assert_ne!(start_operation, result_operation);
        let mut turn = projection_turn();
        turn.execution_events = vec![
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: start_operation.clone(),
                recorded_at: 1_100,
                event: started.clone(),
            },
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: result_operation.clone(),
                recorded_at: 1_200,
                event: result.clone(),
            },
        ];
        let counter = ApproximateCounter::new().unwrap();
        let projected = checkpoint_projection(&counter, &[turn]);
        assert_eq!(projected.len(), 4);
        assert_eq!(projected[1].tool_calls[0].id, "call-a");
        assert_eq!(projected[1].tool_calls[0].name, "read_file");
        assert_eq!(
            projected[1].tool_calls[0].arguments_json,
            r#"{"path":"src/lib.rs"}"#
        );
        assert_eq!(projected[1].content, "I will inspect the file.");
        assert_eq!(
            projected[1].tool_calls[0].provider_metadata,
            provider_metadata
        );
        assert_eq!(projected[2].role, axocoatl_core::MessageRole::Tool);
        assert_eq!(projected[2].tool_call_id.as_deref(), Some("call-a"));

        let (second_start_operation, second_started) =
            session_tool_execution_event_with_provider_metadata(
                "turn-a",
                "coder",
                "call-a",
                1,
                "read_file",
                "tool_started",
                "arguments",
                &serde_json::json!({"path":"src/main.rs"}),
                &serde_json::json!({"path":"src/main.rs"}),
                2,
                0,
                1,
                Some(""),
                &provider_metadata,
                None,
            );
        let (second_result_operation, second_result) = session_tool_execution_event(
            "turn-a",
            "coder",
            "call-a",
            1,
            "read_file",
            "tool_result",
            "result",
            &serde_json::json!({"content":"main"}),
            Some(false),
        );
        assert_ne!(start_operation, second_start_operation);
        assert_ne!(result_operation, second_result_operation);
        let mut repeated = projection_turn();
        repeated.execution_events = vec![
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: start_operation.clone(),
                recorded_at: 1_100,
                event: started.clone(),
            },
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: result_operation.clone(),
                recorded_at: 1_200,
                event: result.clone(),
            },
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: second_start_operation,
                recorded_at: 1_300,
                event: second_started,
            },
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: second_result_operation,
                recorded_at: 1_400,
                event: second_result,
            },
        ];
        let projected = checkpoint_projection(&counter, &[repeated]);
        assert_eq!(
            projected
                .iter()
                .filter(|message| !message.tool_calls.is_empty())
                .count(),
            2,
            "reused raw provider ids remain two distinct tool-loop iterations"
        );

        let oversized = serde_json::Value::String("x".repeat(SESSION_TOOL_EVENT_VALUE_CAP * 2));
        let (_, event) = session_tool_execution_event(
            "turn-a",
            "coder",
            "call-b",
            1,
            "read_file",
            "tool_result",
            "result",
            &oversized,
            Some(false),
        );
        let bounded = event.metadata.get("result").unwrap();
        assert_eq!(bounded["truncated"], true);
        assert!(serde_json::to_vec(bounded).unwrap().len() < SESSION_TOOL_EVENT_VALUE_CAP);
    }

    #[test]
    fn checkpoint_projection_does_not_confuse_tool_payload_truncation_with_ledger_truncation() {
        let provider_metadata = axocoatl_core::ProviderMetadata::from([(
            "axocoatl.provider".to_string(),
            "gemini".to_string(),
        )]);
        let provider_arguments = serde_json::json!({
            "path": "src/lib.rs",
            "truncated": true,
        });
        let executed_arguments = serde_json::json!({
            "path": "sandbox/src/lib.rs",
            "truncated": true,
        });
        let tool_result = serde_json::json!({
            "content": "the bounded result the live model received",
            "truncated": true,
        });
        let (start_operation, started) = session_tool_execution_event_with_provider_metadata(
            "turn-a",
            "coder",
            "call-a",
            0,
            "read_file",
            "tool_started",
            "arguments",
            &executed_arguments,
            &provider_arguments,
            1,
            0,
            1,
            Some(""),
            &provider_metadata,
            None,
        );
        let (result_operation, result) = session_tool_execution_event(
            "turn-a",
            "coder",
            "call-a",
            0,
            "read_file",
            "tool_result",
            "result",
            &tool_result,
            Some(false),
        );
        assert_eq!(started.metadata["arguments_truncated"], false);
        assert_eq!(started.metadata["provider_arguments_truncated"], false);
        assert_eq!(result.metadata["result_truncated"], false);

        let mut turn = projection_turn();
        turn.execution_events = vec![
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: start_operation,
                recorded_at: 1_100,
                event: started,
            },
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: result_operation,
                recorded_at: 1_200,
                event: result,
            },
        ];
        let counter = ApproximateCounter::new().unwrap();
        let projected = checkpoint_projection(&counter, &[turn]);
        assert_eq!(projected.len(), 4);
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&projected[1].tool_calls[0].arguments_json)
                .unwrap(),
            provider_arguments
        );
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&projected[2].content).unwrap(),
            tool_result
        );
    }

    #[test]
    fn checkpoint_projection_rejects_missing_or_duplicate_call_occurrences() {
        let counter = ApproximateCounter::new().unwrap();
        let provider_metadata = axocoatl_core::ProviderMetadata::from([(
            "axocoatl.provider".to_string(),
            "gemini".to_string(),
        )]);
        let make_start = |call_index, assistant_content| {
            session_tool_execution_event_with_provider_metadata(
                "turn-a",
                "coder",
                "call-a",
                0,
                "read_file",
                "tool_started",
                "arguments",
                &serde_json::json!({"path":"src/lib.rs"}),
                &serde_json::json!({"path":"src/lib.rs"}),
                1,
                call_index,
                2,
                assistant_content,
                &provider_metadata,
                None,
            )
        };
        let (first_operation, first) = make_start(0, Some(""));
        let (second_operation, second) = make_start(1, None);
        let (result_operation, result) = session_tool_execution_event(
            "turn-a",
            "coder",
            "call-a",
            0,
            "read_file",
            "tool_result",
            "result",
            &serde_json::json!({"content":"source"}),
            Some(false),
        );
        let mut duplicate = projection_turn();
        duplicate.execution_events = vec![
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: first_operation,
                recorded_at: 1_100,
                event: first,
            },
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: second_operation,
                recorded_at: 1_200,
                event: second,
            },
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: result_operation,
                recorded_at: 1_300,
                event: result,
            },
        ];
        assert_eq!(checkpoint_projection(&counter, &[duplicate]).len(), 2);

        let (start_operation, mut started) = session_tool_execution_event_with_provider_metadata(
            "turn-a",
            "coder",
            "call-b",
            0,
            "read_file",
            "tool_started",
            "arguments",
            &serde_json::json!({"path":"src/lib.rs"}),
            &serde_json::json!({"path":"src/lib.rs"}),
            2,
            0,
            1,
            Some(""),
            &provider_metadata,
            None,
        );
        started.metadata.remove("occurrence");
        let (result_operation, result) = session_tool_execution_event(
            "turn-a",
            "coder",
            "call-b",
            0,
            "read_file",
            "tool_result",
            "result",
            &serde_json::json!({"content":"source"}),
            Some(false),
        );
        let mut missing = projection_turn();
        missing.execution_events = vec![
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: start_operation,
                recorded_at: 1_100,
                event: started,
            },
            axocoatl_session::SessionTurnExecutionEvent {
                operation_id: result_operation,
                recorded_at: 1_200,
                event: result,
            },
        ];
        assert_eq!(checkpoint_projection(&counter, &[missing]).len(), 2);
    }

