    #[tokio::test]
    async fn dormant_podman_defers_exact_cleanup_in_shared_bootstrap_reconciler() {
        for readiness in [
            axocoatl_isolation::podman::PodmanReadiness::MachineStopped,
            axocoatl_isolation::podman::PodmanReadiness::MachineMissing,
            axocoatl_isolation::podman::PodmanReadiness::NotInstalled,
        ] {
            let data = tempfile::tempdir().unwrap();
            let work = tempfile::tempdir().unwrap();
            let mut sessions = SessionStore::new(data.path().join("sessions")).unwrap();
            let session = sessions
                .create_with_environment(
                    "Dormant local runtime",
                    "wsp-dormant-runtime",
                    work.path(),
                    SessionMode::SingleAgent {
                        agent_id: "test-agent".into(),
                    },
                    Vec::new(),
                    Vec::new(),
                    None,
                    None,
                    false,
                    true,
                )
                .unwrap();
            sessions
                .set_environment(
                    &session.id,
                    SessionEnvironmentState::Ready,
                    Some("axocoatl-base:latest".into()),
                    Some(SessionRuntimeIdentity {
                        backend: "podman".into(),
                        id: session.id.clone(),
                        remote_root: None,
                        control_plane: None,
                        data_plane_domain: None,
                        authority_fingerprint: None,
                        ownership_token: None,
                        cleanup_confirmed: false,
                    }),
                    Vec::new(),
                    None,
                )
                .unwrap();
            drop(sessions);

            AxocoatlDaemon::reconcile_persisted_session_records_with_podman_readiness(
                &test_config(),
                &SecureDir::open(data.path()).unwrap(),
                Some(readiness.clone()),
            )
            .await
            .unwrap_or_else(|error| {
                panic!("{readiness:?} must not make bootstrap/offline reads fail: {error}")
            });

            let mut reopened = SessionStore::new(data.path().join("sessions")).unwrap();
            reopened.load_all().unwrap();
            let retained = reopened.get(&session.id).unwrap();
            assert_eq!(
                retained.environment.runtime.as_ref().map(|runtime| (
                    runtime.backend.as_str(),
                    runtime.id.as_str(),
                    runtime.cleanup_confirmed
                )),
                Some(("podman", session.id.as_str(), false)),
                "dormant containers stay non-executing and retain exact cleanup evidence until the next local start"
            );
        }
    }

