    #[tokio::test]
    async fn way_primary_route_rate_limit_does_not_silently_fallback() {
        let config = fallback_test_config();
        let primary_calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let fallback_calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let mut registry = ProviderRegistry::new();
        registry.register(Arc::new(FallbackRouteProbe {
            id: "openai",
            model: "primary-model",
            rate_limited: true,
            calls: primary_calls.clone(),
            model_overrides: Arc::new(StdMutex::new(Vec::new())),
        }));
        registry.register(Arc::new(FallbackRouteProbe {
            id: "anthropic",
            model: "fallback-default",
            rate_limited: false,
            calls: fallback_calls.clone(),
            model_overrides: Arc::new(StdMutex::new(Vec::new())),
        }));

        let way_provider = AxocoatlDaemon::resolve_primary_provider(
            &config,
            &registry,
            "openai",
            Some("primary-model"),
        )
        .unwrap();
        let mut request = axocoatl_llm::ChatRequest::simple("attempt this change");
        request.model_override = Some("primary-model".to_string());
        assert!(matches!(
            way_provider.chat(request).await,
            Err(axocoatl_llm::ProviderError::RateLimited { .. })
        ));
        assert_eq!(primary_calls.load(std::sync::atomic::Ordering::SeqCst), 1,);
        assert_eq!(
            fallback_calls.load(std::sync::atomic::Ordering::SeqCst),
            0,
            "a Way must not switch routes behind its persisted provider/model/cost labels",
        );
    }

    fn uneven_legacy_rewind_transcript() -> Vec<SessionTranscriptMessage> {
        let root = tempfile::tempdir().unwrap();
        let mut store = SessionTurnStore::open(root.path()).unwrap();
        for turn_id in ["turn-a", "turn-b", "turn-c"] {
            store
                .begin(BeginSessionTurn {
                    turn_id: Some(turn_id.to_string()),
                    session_id: "session-rewind".to_string(),
                    user_input: format!("request {turn_id}"),
                    agent_id: Some("coder".to_string()),
                    model: Some("model".to_string()),
                    context: Vec::new(),
                    idempotency_key: Some(format!("request-{turn_id}")),
                    metadata: serde_json::Map::new(),
                })
                .unwrap();
        }
        store
            .transition(
                "turn-a",
                "finish-turn-a",
                TransitionSessionTurn {
                    status: SessionTurnLifecycle::Completed,
                    final_output: Some("answer a".to_string()),
                    error: None,
                    metadata: serde_json::Map::new(),
                },
            )
            .unwrap();
        store
            .transition(
                "turn-b",
                "fail-turn-b",
                TransitionSessionTurn {
                    status: SessionTurnLifecycle::Failed,
                    final_output: None,
                    error: Some("failed before output".to_string()),
                    metadata: serde_json::Map::new(),
                },
            )
            .unwrap();
        store
            .transition(
                "turn-c",
                "finish-turn-c",
                TransitionSessionTurn {
                    status: SessionTurnLifecycle::Completed,
                    final_output: Some("answer c".to_string()),
                    error: None,
                    metadata: serde_json::Map::new(),
                },
            )
            .unwrap();
        store.transcript("session-rewind")
    }

    #[test]
    fn legacy_rewind_resolves_zero_uneven_turns_and_all_history_exactly() {
        let transcript = uneven_legacy_rewind_transcript();
        let counts = ["turn-a", "turn-b", "turn-c"].map(|turn_id| {
            transcript
                .iter()
                .filter(|message| message.turn_id == turn_id)
                .count()
        });
        assert_eq!(counts, [2, 1, 2]);

        assert_eq!(legacy_rewind_turn_boundary(&transcript, 0).unwrap(), None);
        assert_eq!(
            legacy_rewind_turn_boundary(&transcript, 2).unwrap(),
            Some("turn-a".to_string())
        );
        assert_eq!(
            legacy_rewind_turn_boundary(&transcript, 3).unwrap(),
            Some("turn-b".to_string())
        );
        assert_eq!(
            legacy_rewind_turn_boundary(&transcript, transcript.len()).unwrap(),
            Some("turn-c".to_string())
        );
    }

    #[test]
    fn legacy_rewind_rejects_intra_turn_and_out_of_range_boundaries() {
        let transcript = uneven_legacy_rewind_transcript();
        for keep in [1, 4] {
            let error = legacy_rewind_turn_boundary(&transcript, keep)
                .unwrap_err()
                .to_string();
            assert!(error.contains("splits turn"), "{error}");
        }
        let error = legacy_rewind_turn_boundary(&transcript, transcript.len() + 1)
            .unwrap_err()
            .to_string();
        assert!(
            error.contains("exceeds the visible transcript length"),
            "{error}"
        );
    }

    #[test]
    fn session_roles_reject_direct_workers_and_do_not_double_run_coordinator_workflows() {
        let config = role_test_config();
        let worker = config
            .agents
            .iter()
            .find(|agent| agent.id == "worker")
            .unwrap();
        let direct_error = validate_direct_actor_role(worker).unwrap_err().to_string();
        assert!(direct_error.contains("start or restart its coordinator"));
        assert!(validate_direct_actor_role(
            config
                .agents
                .iter()
                .find(|agent| agent.id == "lead")
                .unwrap(),
        )
        .is_ok());
        assert!(validate_rewind_agent(&config, "auto-code").is_ok());
        let rewind_error = validate_rewind_agent(&config, "lead")
            .unwrap_err()
            .to_string();
        assert!(rewind_error.contains("coordinator-owned Worker checkpoints"));
        assert!(validate_session_mode(
            &config,
            &SessionMode::SingleAgent {
                agent_id: "lead".into(),
            },
        )
        .is_ok());
        assert!(validate_session_mode(
            &config,
            &SessionMode::Custom {
                agents: vec!["auto-code".into(), "lead".into()],
            },
        )
        .is_ok());

        for mode in [
            SessionMode::SingleAgent {
                agent_id: "worker".into(),
            },
            SessionMode::Custom {
                agents: vec!["worker".into()],
            },
        ] {
            let error = validate_session_mode(&config, &mode)
                .expect_err("a coordinator-owned Worker must never be a direct Session target")
                .to_string();
            assert!(error.contains("coordinator-owned worker"), "{error}");
        }

        let coordinated = config
            .workflows
            .iter()
            .find(|workflow| workflow.id == "coordinated")
            .unwrap();
        assert_eq!(
            AxocoatlDaemon::session_workflow_agents(&config, coordinated).unwrap(),
            vec!["lead"],
            "the coordinator owns its declared Worker and the Session must not execute that Worker again",
        );
        let autonomous = config
            .workflows
            .iter()
            .find(|workflow| workflow.id == "autonomous")
            .unwrap();
        assert_eq!(
            AxocoatlDaemon::session_workflow_agents(&config, autonomous).unwrap(),
            vec!["auto-review", "auto-code"],
            "an autonomous lattice keeps its configured roster",
        );
        assert_eq!(
            AxocoatlDaemon::topo_order(&autonomous.agents, &config),
            vec!["auto-code", "auto-review"],
            "the existing autonomous lattice dependency order remains unchanged",
        );
    }

