    #[tokio::test]
    async fn early_bootstrap_reconciles_runtime_creation_before_later_failure() {
        let data = tempfile::tempdir().unwrap();
        let work = tempfile::tempdir().unwrap();
        let mut sessions = SessionStore::new(data.path().join("sessions")).unwrap();
        let session = sessions
            .create_with_environment(
                "Interrupted create",
                "wsp-interrupted-create",
                work.path(),
                SessionMode::SingleAgent {
                    agent_id: "test-agent".into(),
                },
                Vec::new(),
                Vec::new(),
                None,
                None,
                false,
                true,
            )
            .unwrap();
        let preparing = sessions
            .set_environment(
                &session.id,
                SessionEnvironmentState::Preparing,
                Some("e2b:base".into()),
                None,
                Vec::new(),
                None,
            )
            .unwrap();
        let creation_token = test_e2b_ownership_token(&preparing);
        let (api_url, mut requests, server) = start_fake_e2b_control_plane(vec![
            test_e2b_owned_list("committed-before-restart", &creation_token),
            test_e2b_owned_sandbox("committed-before-restart", &creation_token),
            test_http_response("204 No Content", ""),
        ])
        .await;
        let config = e2b_test_config(&api_url);
        sessions
            .set_runtime_creation_if_preparing(
                &session.id,
                preparing.environment.generation,
                SessionRuntimeCreationAttempt {
                    backend: "e2b".into(),
                    token: creation_token.clone(),
                    remote_root: "/home/user/repository".into(),
                    control_plane: api_url.clone(),
                    data_plane_domain: "sandbox.test".into(),
                    authority_fingerprint: AxocoatlDaemon::e2b_authority_fingerprint("test-key"),
                    discovered_ids: Vec::new(),
                },
            )
            .unwrap();
        let session_id = session.id;
        drop(sessions);

        let result = async {
            AxocoatlDaemon::reconcile_persisted_session_records(
                &config,
                &SecureDir::open(data.path()).unwrap(),
            )
            .await?;
            Err::<(), DaemonError>(DaemonError::Provider(
                "injected later bootstrap failure".into(),
            ))
        }
        .await;
        assert!(result
            .unwrap_err()
            .to_string()
            .contains("injected later bootstrap failure"));
        let list = requests.recv().await.expect("metadata LIST request");
        assert!(list.starts_with("GET /v2/sandboxes?"));
        assert!(list.contains("metadata=axocoatl_creation_token%3D"));
        let proof = requests.recv().await.expect("exact ownership GET");
        assert!(proof.starts_with("GET /sandboxes/committed-before-restart HTTP/1.1"));
        let delete = requests.recv().await.expect("exact DELETE request");
        assert!(delete.starts_with("DELETE /sandboxes/committed-before-restart HTTP/1.1"));
        server.await.unwrap();

        let mut reopened = SessionStore::new(data.path().join("sessions")).unwrap();
        reopened.load_all().unwrap();
        let session = reopened.get(&session_id).unwrap();
        assert!(session.environment.runtime_creation.is_none());
        assert!(session.environment.runtime.is_none());
    }

