    #[tokio::test]
    async fn second_data_dir_owner_fails_before_any_runtime_lifecycle_request() {
        let (api_url, mut requests, server) =
            start_fake_e2b_control_plane(vec![test_http_response("204 No Content", "")]).await;
        let config = e2b_test_config(&api_url);
        let data = tempfile::tempdir().unwrap();
        let work = tempfile::tempdir().unwrap();
        let mut sessions = SessionStore::new(data.path().join("sessions")).unwrap();
        let session = sessions
            .create_with_environment(
                "Live owner",
                "wsp-live-owner",
                work.path(),
                SessionMode::SingleAgent {
                    agent_id: "test-agent".into(),
                },
                Vec::new(),
                Vec::new(),
                None,
                None,
                false,
                true,
            )
            .unwrap();
        sessions
            .set_environment(
                &session.id,
                SessionEnvironmentState::Ready,
                Some("e2b:base".into()),
                Some(SessionRuntimeIdentity {
                    backend: "e2b".into(),
                    id: "live-owned-id".into(),
                    remote_root: Some("/home/user/repository".into()),
                    control_plane: Some(api_url),
                    data_plane_domain: Some("sandbox.test".into()),
                    authority_fingerprint: Some(AxocoatlDaemon::e2b_authority_fingerprint(
                        "test-key",
                    )),
                    ownership_token: Some(test_e2b_ownership_token(&session)),
                    cleanup_confirmed: false,
                }),
                Vec::new(),
                None,
            )
            .unwrap();
        drop(sessions);

        let data_root = SecureDir::open(data.path()).unwrap();
        let _owner = DataDirLease::acquire(&data_root).expect("first data-dir owner");
        let error =
            match AxocoatlDaemon::acquire_data_dir_lease_and_reconcile(&config, &data_root).await {
                Ok(_) => panic!("second data-dir owner must fail"),
                Err(error) => error,
            };
        assert!(error.to_string().contains("already owned"));
        assert!(
            tokio::time::timeout(Duration::from_millis(100), requests.recv())
                .await
                .is_err(),
            "lock rejection must happen before PAUSE/DELETE/LIST"
        );
        server.abort();
    }

    #[test]
    fn local_runtime_authority_is_stable_and_scoped_to_one_data_root() {
        let first = tempfile::tempdir().unwrap();
        let second = tempfile::tempdir().unwrap();

        let first_root = SecureDir::open_or_create_all(first.path()).unwrap();
        let equivalent_root = SecureDir::open_or_create_all(first.path().join(".")).unwrap();
        let second_root = SecureDir::open_or_create_all(second.path()).unwrap();
        let first_authority = local_runtime_authority(&first_root).unwrap();
        let equivalent_first = local_runtime_authority(&equivalent_root).unwrap();
        let second_authority = local_runtime_authority(&second_root).unwrap();

        assert_eq!(first_authority, equivalent_first);
        assert_ne!(first_authority, second_authority);
        assert_eq!(first_authority.len(), 64);
        assert!(first_authority.bytes().all(|byte| byte.is_ascii_hexdigit()));
        assert_eq!(second_authority.len(), 64);
        assert!(second_authority
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit()));
    }

