        let list = requests.recv().await.expect("pause ownership LIST");
        assert!(list.starts_with("GET /v2/sandboxes?"));
        let proof = requests.recv().await.expect("pause ownership GET");
        assert!(proof.starts_with("GET /sandboxes/ready-pause-retry-id HTTP/1.1"));
        let pause = requests.recv().await.expect("attempted PAUSE request");
