    fn attempt_cleanup_budget_exceeds_podmans_historical_stop_grace() {
        assert!(ATTEMPT_CONTAINER_STOP_TIMEOUT > Duration::from_secs(10));
    }

    async fn wait_until_stream_gate_is_owned(gate: &tokio::sync::Mutex<()>) {
        for _ in 0..100 {
            if gate.try_lock().is_err() {
                return;
            }
            tokio::task::yield_now().await;
        }
        panic!("stream lifecycle commit did not acquire its gate");
    }

    #[tokio::test]
    async fn reconnect_cut_cannot_hide_a_newly_owned_session_turn() {
        let gate = Arc::new(tokio::sync::Mutex::new(()));
        let active = Arc::new(tokio::sync::Mutex::new(HashMap::new()));
        let bus = crate::stream::StreamBus::new(16);
        let mut subscriber = bus.subscribe();

        // Freeze the ownership registry after the lifecycle commit obtains
        // the outer gate. A pre-fix snapshot could inspect the empty registry,
        // then include Accepted/Start in its cursor and lose the live turn.
        let active_guard = active.lock().await;
        let start_gate = gate.clone();
        let start_active = active.clone();
        let start_bus = bus.clone();
        let start = tokio::spawn(async move {
            commit_session_start(
                &start_gate,
                &start_active,
                &start_bus,
                "session-b",
                "turn-b",
                AgentRunControl::new(AgentRunId::new("turn-b")),
            )
            .await;
        });
        wait_until_stream_gate_is_owned(&gate).await;
        let cut_gate = gate.clone();
        let cut_active = active.clone();
        let cut_bus = bus.clone();
        let cut =
            tokio::spawn(
                async move { live_run_snapshot_cut(&cut_gate, &cut_active, &cut_bus).await },
            );

        drop(active_guard);
        start.await.unwrap();
        let (cursor, snapshot, environment_transitions, attempt_ownerships) = cut.await.unwrap();
        assert!(environment_transitions.is_empty());
        assert!(attempt_ownerships.is_empty());
        assert_eq!(cursor, 2);
        assert_eq!(snapshot.len(), 1);
        assert_eq!(snapshot[0].workflow, "session-b");
        assert_eq!(snapshot[0].turn_id.as_deref(), Some("turn-b"));

        for expected_sequence in 1..=2 {
            let envelope = subscriber.recv_sequenced().await.unwrap();
            assert_eq!(envelope.sequence, expected_sequence);
            assert!(envelope.sequence <= cursor);
        }
    }

    #[tokio::test]
    async fn reconnect_cut_cannot_resurrect_a_terminal_session_turn() {
        let gate = Arc::new(tokio::sync::Mutex::new(()));
        let active = Arc::new(tokio::sync::Mutex::new(HashMap::new()));
        let bus = crate::stream::StreamBus::new(16);
        let mut subscriber = bus.subscribe();
        commit_session_start(
            &gate,
            &active,
            &bus,
            "session-a",
            "turn-a",
            AgentRunControl::new(AgentRunId::new("turn-a")),
        )
        .await;

        // Freeze the ownership registry after terminal commit obtains the
        // outer gate. A pre-fix snapshot could retain this stale active row,
        // include the terminal sequence in its cursor, then expose a ghost
        // Stop control forever.
        let active_guard = active.lock().await;
        let terminal_gate = gate.clone();
        let terminal_active = active.clone();
        let terminal_bus = bus.clone();
        let terminal = tokio::spawn(async move {
            commit_session_terminal(
                &terminal_gate,
                &terminal_active,
                &terminal_bus,
                "session-a",
                "turn-a",
                crate::stream::StreamFrame::SessionDone {
                    session: "session-a".to_string(),
                    turn_id: Some("turn-a".to_string()),
                    input_tokens: 3,
                    output_tokens: 5,
                    reasoning_tokens: 0,
                    token_usage_known: true,
                },
            )
            .await;
        });
        wait_until_stream_gate_is_owned(&gate).await;
        let cut_gate = gate.clone();
        let cut_active = active.clone();
        let cut_bus = bus.clone();
        let cut =
            tokio::spawn(
                async move { live_run_snapshot_cut(&cut_gate, &cut_active, &cut_bus).await },
            );

        drop(active_guard);
        terminal.await.unwrap();
        let (cursor, snapshot, environment_transitions, attempt_ownerships) = cut.await.unwrap();
        assert!(environment_transitions.is_empty());
        assert!(attempt_ownerships.is_empty());
        assert_eq!(cursor, 3);
        assert!(snapshot.iter().all(|run| run.workflow != "session-a"));
        assert!(!active.lock().await.contains_key("session-a"));

        for expected_sequence in 1..=3 {
            let envelope = subscriber.recv_sequenced().await.unwrap();
            assert_eq!(envelope.sequence, expected_sequence);
            assert!(envelope.sequence <= cursor);
        }
    }

    #[tokio::test]
    async fn terminal_commit_wins_over_a_queued_reattach_replay() {
        let gate = Arc::new(tokio::sync::Mutex::new(()));
        let active = Arc::new(tokio::sync::Mutex::new(HashMap::new()));
        let bus = crate::stream::StreamBus::new(16);
        let mut subscriber = bus.subscribe();
        commit_session_start(
            &gate,
            &active,
            &bus,
            "session-a",
            "turn-a",
            AgentRunControl::new(AgentRunId::new("turn-a")),
        )
        .await;

        let active_guard = active.lock().await;
        let terminal_gate = gate.clone();
        let terminal_active = active.clone();
        let terminal_bus = bus.clone();
        let terminal = tokio::spawn(async move {
            commit_session_terminal(
                &terminal_gate,
                &terminal_active,
                &terminal_bus,
                "session-a",
                "turn-a",
                crate::stream::StreamFrame::SessionDone {
                    session: "session-a".to_string(),
                    turn_id: Some("turn-a".to_string()),
                    input_tokens: 3,
                    output_tokens: 5,
                    reasoning_tokens: 0,
                    token_usage_known: true,
                },
            )
            .await;
        });
        wait_until_stream_gate_is_owned(&gate).await;
        let replay_gate = gate.clone();
        let replay_active = active.clone();
        let replay_bus = bus.clone();
        let replay = tokio::spawn(async move {
            replay_session_start(
                &replay_gate,
                &replay_active,
                &replay_bus,
                "session-a",
                "turn-a",
            )
            .await
        });

        drop(active_guard);
        terminal.await.unwrap();
        assert!(!replay.await.unwrap());
        assert!(!bus.contains_run("session-a"));
        for expected_sequence in 1..=3 {
            assert_eq!(
                subscriber.recv_sequenced().await.unwrap().sequence,
                expected_sequence
            );
        }
        assert!(matches!(
            subscriber.try_recv(),
            Err(tokio::sync::broadcast::error::TryRecvError::Empty)
        ));
    }

    #[tokio::test]
    async fn preflight_error_does_not_release_another_turns_live_ownership() {
        let gate = tokio::sync::Mutex::new(());
        let active = tokio::sync::Mutex::new(HashMap::new());
        let bus = crate::stream::StreamBus::new(16);
        let mut subscriber = bus.subscribe();
        commit_session_start(
            &gate,
            &active,
            &bus,
            "session-a",
            "turn-a",
            AgentRunControl::new(AgentRunId::new("turn-a")),
        )
        .await;

        commit_session_preflight_error(
            &gate,
            &bus,
            "session-a",
            "turn-b",
            &DaemonError::SessionConflict("turn-a is already running".to_string()),
        )
        .await;

        assert_eq!(active.lock().await["session-a"].turn_id, "turn-a");
        assert_eq!(
            bus.run("session-a").and_then(|run| run.turn_id),
            Some("turn-a".to_string())
        );
        assert_eq!(subscriber.recv_sequenced().await.unwrap().sequence, 1);
        assert_eq!(subscriber.recv_sequenced().await.unwrap().sequence, 2);
        let error = subscriber.recv_sequenced().await.unwrap();
        assert_eq!(error.sequence, 3);
        assert!(matches!(
            error.frame,
            crate::stream::StreamFrame::SessionError {
                ref session,
                turn_id: Some(ref turn_id),
                ..
            } if session == "session-a" && turn_id == "turn-b"
        ));
    }

    #[tokio::test]
    async fn close_cancels_exact_active_turn_before_waiting_for_workspace_lease() {
        let active_turns = Arc::new(tokio::sync::Mutex::new(HashMap::new()));
        let active_control = AgentRunControl::new(AgentRunId::new("turn-active"));
        let other_control = AgentRunControl::new(AgentRunId::new("turn-other"));
        active_turns.lock().await.insert(
            "session-active".to_string(),
            ActiveSessionTurn {
                turn_id: "turn-active".to_string(),
                control: active_control.clone(),
            },
        );
        active_turns.lock().await.insert(
            "session-other".to_string(),
            ActiveSessionTurn {
                turn_id: "turn-other".to_string(),
                control: other_control.clone(),
            },
        );

        let stale = request_active_session_turn_cancellation(
            &active_turns,
            "session-active",
            Some("turn-stale"),
        )
        .await;
        assert!(matches!(stale, Err(DaemonError::Session(_))));
        assert!(
            !active_control.is_cancelled(),
            "a stale exact Stop target must not cancel the current turn"
        );

        // Model the normal turn holding the per-Session operation lease while
        // Close starts. Close's cancellation phase must complete even though
        // its subsequent lease acquisition cannot.
        let operation = Arc::new(tokio::sync::Mutex::new(()));
        let turn_lease = operation.clone().lock_owned().await;
        let active_for_close = active_turns.clone();
        let operation_for_close = operation.clone();
        let close = tokio::spawn(async move {
            let requested =
                request_active_session_turn_cancellation(&active_for_close, "session-active", None)
                    .await?;
            let _cleanup_lease = operation_for_close.lock_owned().await;
            Ok::<_, DaemonError>(requested)
        });

        tokio::time::timeout(Duration::from_millis(250), active_control.cancelled())
            .await
            .expect("Close must request cancellation before waiting for the operation lease");
        assert!(
            !other_control.is_cancelled(),
            "Close must not cancel another Session's turn"
        );
        assert!(
            !close.is_finished(),
            "Close should still wait for the running turn to reach its safe boundary"
        );

        drop(turn_lease);
        assert_eq!(close.await.unwrap().unwrap(), Some(true));
    }

